        )
        .unwrap();
        let changed = causal_scaled_dot_product_self_attention(
            &constant(&[1, 3, 2], &QUERY),
            &constant(&[1, 3, 2], &[3.0, 0.0, -1.0, 2.0, -2.0, 4.0]),
