        let pass = causal_scaled_dot_product_self_attention(&query, &key, &value).unwrap();
        let prefix_seed = constant(&[1, 3, 2], &[1.0, -1.0, 0.5, 2.0, 0.0, 0.0]);
        sum_to_scalar(pass.output().mul(&prefix_seed).unwrap())
