//! Central differences and sampled tensor-coordinate gradient checks.

use std::error::Error;
use std::fmt;

use crate::tensor::storage::Tensor;
use crate::tensor::view::{TensorView, TensorViewError};

/// The side of a central-difference probe that failed.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DifferenceSide {
    Minus,
    Center,
    Plus,
}

impl fmt::Display for DifferenceSide {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Minus => formatter.write_str("minus"),
            Self::Center => formatter.write_str("center"),
            Self::Plus => formatter.write_str("plus"),
        }
    }
}

/// Whether the rounded probes are equally spaced around the requested point.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DifferenceStencil {
    Symmetric,
    Unequal,
}

impl fmt::Display for DifferenceStencil {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Symmetric => formatter.write_str("symmetric"),
            Self::Unequal => formatter.write_str("unequal"),
        }
    }
}

// region:gradcheck-errors
/// A rejected numerical derivative, comparison, sample request, or tensor read.
#[derive(Clone, Debug, PartialEq)]
pub enum GradCheckError {
    InvalidStep {
        step: f64,
    },
    NonFinitePoint {
        point: f64,
    },
    PerturbationNotFinite {
        side: DifferenceSide,
        point: f64,
        step: f64,
    },
    PerturbationUnchanged {
        side: DifferenceSide,
        point: f64,
        step: f64,
    },
    InvalidActualSpacing {
        side: DifferenceSide,
        point: f64,
        probe: f64,
        spacing: f64,
    },
    NonFiniteStencilWeight {
        side: DifferenceSide,
        value: f64,
    },
    NonFiniteEvaluation {
        side: DifferenceSide,
        value: f64,
    },
    NonFiniteOneSidedSlope {
        side: DifferenceSide,
        value: f64,
    },
    NonFiniteNumericalGradient {
        value: f64,
    },
    InvalidTolerance {
        tolerance: f64,
    },
    NonFiniteAnalyticGradient {
        value: f64,
    },
    GradientShapeMismatch {
        parameters: Vec<usize>,
        analytic: Vec<usize>,
    },
    ShapeOverflow,
    EmptyTensor,
    ZeroSamples,
    SampleAllocationFailed {
        samples: usize,
        rank: usize,
    },
    View(TensorViewError),
    AtCoordinate {
        coordinate: Vec<usize>,
        source: Box<GradCheckError>,
    },
}

impl fmt::Display for GradCheckError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::InvalidStep { step } => write!(
                formatter,
                "central-difference requested step {step:?} must be positive and finite"
            ),
            Self::NonFinitePoint { point } => {
                write!(formatter, "gradient-check point {point:?} must be finite")
            }
            Self::PerturbationNotFinite { side, point, step } => write!(
                formatter,
                "{side} perturbation from point {point:?} by step {step:?} is not finite"
            ),
            Self::PerturbationUnchanged { side, point, step } => write!(
                formatter,
                "{side} perturbation from point {point:?} by step {step:?} rounds back to the point"
            ),
            Self::InvalidActualSpacing {
                side,
                point,
                probe,
                spacing,
            } => write!(
                formatter,
                "{side} actual spacing from point {point:?} to probe {probe:?} must be positive and finite, got {spacing:?}"
            ),
            Self::NonFiniteStencilWeight { side, value } => {
                write!(formatter, "{side} stencil weight is not finite: {value:?}")
            }
            Self::NonFiniteEvaluation { side, value } => {
                write!(formatter, "{side} function evaluation returned {value:?}")
            }
            Self::NonFiniteOneSidedSlope { side, value } => {
                write!(formatter, "{side} one-sided slope is not finite: {value:?}")
            }
            Self::NonFiniteNumericalGradient { value } => {
                write!(
                    formatter,
                    "central difference produced non-finite gradient {value:?}"
                )
            }
            Self::InvalidTolerance { tolerance } => write!(
                formatter,
                "gradient-check tolerance {tolerance:?} must be finite and nonnegative"
            ),
            Self::NonFiniteAnalyticGradient { value } => {
                write!(formatter, "analytic gradient {value:?} must be finite")
            }
            Self::GradientShapeMismatch {
                parameters,
                analytic,
            } => write!(
                formatter,
                "parameter shape {parameters:?} does not match analytic-gradient shape {analytic:?}"
            ),
            Self::ShapeOverflow => formatter.write_str("sampled tensor shape overflows usize"),
            Self::EmptyTensor => {
                formatter.write_str("sampled tensor gradient check needs at least one value")
            }
            Self::ZeroSamples => {
                formatter.write_str("sampled tensor gradient check needs at least one sample")
            }
            Self::SampleAllocationFailed { samples, rank } => write!(
                formatter,
                "cannot allocate {samples} sampled coordinates of rank {rank}"
            ),
            Self::View(error) => error.fmt(formatter),
            Self::AtCoordinate { coordinate, source } => {
                write!(
                    formatter,
                    "gradient check at coordinate {coordinate:?} failed: {source}"
                )
            }
        }
    }
}

impl Error for GradCheckError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            Self::View(error) => Some(error),
            Self::AtCoordinate { source, .. } => Some(source.as_ref()),
            _ => None,
        }
    }
}

impl From<TensorViewError> for GradCheckError {
    fn from(error: TensorViewError) -> Self {
        Self::View(error)
    }
}
// endregion:gradcheck-errors

/// Every value used by one central-difference estimate.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct CentralDifference {
    pub point: f64,
    pub requested_step: f64,
    pub minus_point: f64,
    pub plus_point: f64,
    pub minus_spacing: f64,
    pub plus_spacing: f64,
    pub minus_value: f64,
    pub center_value: f64,
    pub plus_value: f64,
    pub left_slope: f64,
    pub right_slope: f64,
    pub left_weight: f64,
    pub right_weight: f64,
    pub stencil: DifferenceStencil,
    pub derivative: f64,
}

/// A scale-aware comparison between one analytic and one numerical gradient.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct GradientComparison {
    pub analytic: f64,
    pub numerical: f64,
    pub absolute_error: f64,
    pub scale: f64,
    pub scaled_error: f64,
    pub tolerance: f64,
    pub passed: bool,
}

/// A scale-aware diagnostic comparing the two one-sided secant slopes.
///
/// Disagreement can reveal a kink, an excessively large step, or rounding
/// damage. Agreement does not prove differentiability.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct OneSidedSlopeComparison {
    pub left: f64,
    pub right: f64,
    pub absolute_gap: f64,
    pub scale: f64,
    pub scaled_gap: f64,
    pub tolerance: f64,
    pub consistent: bool,
}

/// The numerical estimate and comparison for one scalar parameter.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct ScalarGradientCheck {
    pub difference: CentralDifference,
    pub comparison: GradientComparison,
}

fn validate_step(step: f64) -> Result<(), GradCheckError> {
    if !step.is_finite() || step <= 0.0 {
        return Err(GradCheckError::InvalidStep { step });
    }
    Ok(())
}

fn validate_tolerance(tolerance: f64) -> Result<(), GradCheckError> {
    if !tolerance.is_finite() || tolerance < 0.0 {
        return Err(GradCheckError::InvalidTolerance { tolerance });
    }
    Ok(())
}

#[derive(Clone, Copy, Debug, PartialEq)]
struct ProbeGeometry {
    minus_point: f64,
    plus_point: f64,
    minus_spacing: f64,
    plus_spacing: f64,
    left_weight: f64,
    right_weight: f64,
    stencil: DifferenceStencil,
}

fn perturbations(point: f64, step: f64) -> Result<ProbeGeometry, GradCheckError> {
    validate_step(step)?;
    if !point.is_finite() {
        return Err(GradCheckError::NonFinitePoint { point });
    }

    let minus_point = point - step;
    if !minus_point.is_finite() {
        return Err(GradCheckError::PerturbationNotFinite {
            side: DifferenceSide::Minus,
            point,
            step,
        });
    }
    if minus_point == point {
        return Err(GradCheckError::PerturbationUnchanged {
            side: DifferenceSide::Minus,
            point,
            step,
        });
    }

    let plus_point = point + step;
    if !plus_point.is_finite() {
        return Err(GradCheckError::PerturbationNotFinite {
            side: DifferenceSide::Plus,
            point,
            step,
        });
    }
    if plus_point == point {
        return Err(GradCheckError::PerturbationUnchanged {
            side: DifferenceSide::Plus,
            point,
            step,
        });
    }

    let minus_spacing = point - minus_point;
    if !minus_spacing.is_finite() || minus_spacing <= 0.0 {
        return Err(GradCheckError::InvalidActualSpacing {
            side: DifferenceSide::Minus,
            point,
            probe: minus_point,
            spacing: minus_spacing,
        });
    }
    let plus_spacing = plus_point - point;
    if !plus_spacing.is_finite() || plus_spacing <= 0.0 {
        return Err(GradCheckError::InvalidActualSpacing {
            side: DifferenceSide::Plus,
            point,
            probe: plus_point,
            spacing: plus_spacing,
        });
    }

    // Scaling first keeps the weight denominator in (1, 2], even when the
    // unscaled sum h_minus + h_plus would overflow.
    let spacing_scale = minus_spacing.max(plus_spacing);
    let scaled_minus = minus_spacing / spacing_scale;
    let scaled_plus = plus_spacing / spacing_scale;
    let scaled_sum = scaled_minus + scaled_plus;
    let left_weight = scaled_plus / scaled_sum;
    if !left_weight.is_finite() {
        return Err(GradCheckError::NonFiniteStencilWeight {
            side: DifferenceSide::Minus,
            value: left_weight,
        });
    }
    let right_weight = scaled_minus / scaled_sum;
    if !right_weight.is_finite() {
        return Err(GradCheckError::NonFiniteStencilWeight {
            side: DifferenceSide::Plus,
            value: right_weight,
        });
    }

    Ok(ProbeGeometry {
        minus_point,
        plus_point,
        minus_spacing,
        plus_spacing,
        left_weight,
        right_weight,
        stencil: if minus_spacing == plus_spacing {
            DifferenceStencil::Symmetric
        } else {
            DifferenceStencil::Unequal
        },
    })
}

// region:central-difference
/// Approximates one derivative from the actual representable probe spacings.
///
/// The callback is evaluated exactly three times, in minus, center, plus order.
/// A meaningful gradient check requires a deterministic, side-effect-free
/// objective that is differentiable and sufficiently smooth throughout the
/// closed probe interval. Known or possible kinks must be excluded or examined
/// with [`compare_one_sided_slopes`]; a passing comparison is evidence for the
/// sampled smooth point, not a universal proof of a derivative.
pub fn central_difference(
    point: f64,
    step: f64,
    mut evaluate: impl FnMut(f64) -> f64,
) -> Result<CentralDifference, GradCheckError> {
    let geometry = perturbations(point, step)?;

    let minus_value = evaluate(geometry.minus_point);
    if !minus_value.is_finite() {
        return Err(GradCheckError::NonFiniteEvaluation {
            side: DifferenceSide::Minus,
            value: minus_value,
        });
    }

    let center_value = evaluate(point);
    if !center_value.is_finite() {
        return Err(GradCheckError::NonFiniteEvaluation {
            side: DifferenceSide::Center,
            value: center_value,
        });
    }

    let plus_value = evaluate(geometry.plus_point);
    if !plus_value.is_finite() {
        return Err(GradCheckError::NonFiniteEvaluation {
            side: DifferenceSide::Plus,
            value: plus_value,
        });
    }

    let left_slope = (center_value - minus_value) / geometry.minus_spacing;
    if !left_slope.is_finite() {
        return Err(GradCheckError::NonFiniteOneSidedSlope {
            side: DifferenceSide::Minus,
            value: left_slope,
        });
    }
    let right_slope = (plus_value - center_value) / geometry.plus_spacing;
    if !right_slope.is_finite() {
        return Err(GradCheckError::NonFiniteOneSidedSlope {
            side: DifferenceSide::Plus,
            value: right_slope,
        });
    }

    let derivative = geometry.left_weight * left_slope + geometry.right_weight * right_slope;
    if !derivative.is_finite() {
        return Err(GradCheckError::NonFiniteNumericalGradient { value: derivative });
    }

    Ok(CentralDifference {
        point,
        requested_step: step,
        minus_point: geometry.minus_point,
        plus_point: geometry.plus_point,
        minus_spacing: geometry.minus_spacing,
        plus_spacing: geometry.plus_spacing,
        minus_value,
        center_value,
        plus_value,
        left_slope,
        right_slope,
        left_weight: geometry.left_weight,
        right_weight: geometry.right_weight,
        stencil: geometry.stencil,
        derivative,
    })
}
// endregion:central-difference

// region:scale-aware-comparison
/// Compares gradients after scaling both by the larger magnitude or one.
pub fn compare_gradients(
    analytic: f64,
    numerical: f64,
    tolerance: f64,
) -> Result<GradientComparison, GradCheckError> {
    validate_tolerance(tolerance)?;
    if !analytic.is_finite() {
        return Err(GradCheckError::NonFiniteAnalyticGradient { value: analytic });
    }
    if !numerical.is_finite() {
        return Err(GradCheckError::NonFiniteNumericalGradient { value: numerical });
    }

    let scale = 1.0_f64.max(analytic.abs()).max(numerical.abs());
    let absolute_error = (analytic - numerical).abs();
    let scaled_error = (analytic / scale - numerical / scale).abs();

    Ok(GradientComparison {
        analytic,
        numerical,
        absolute_error,
        scale,
        scaled_error,
        tolerance,
        passed: scaled_error <= tolerance,
    })
}

/// Compares the recorded left and right secant slopes without claiming proof.
///
/// A failed diagnostic can indicate a nondifferentiable kink, a step that is
/// too large for the local curvature, or floating-point rounding. A passing
/// diagnostic cannot establish differentiability on its own.
pub fn compare_one_sided_slopes(
    difference: &CentralDifference,
    tolerance: f64,
) -> Result<OneSidedSlopeComparison, GradCheckError> {
    validate_tolerance(tolerance)?;
    let left = difference.left_slope;
    if !left.is_finite() {
        return Err(GradCheckError::NonFiniteOneSidedSlope {
            side: DifferenceSide::Minus,
            value: left,
        });
    }
    let right = difference.right_slope;
    if !right.is_finite() {
        return Err(GradCheckError::NonFiniteOneSidedSlope {
            side: DifferenceSide::Plus,
            value: right,
        });
    }
    let scale = 1.0_f64.max(left.abs()).max(right.abs());
    let absolute_gap = (left - right).abs();
    let scaled_gap = (left / scale - right / scale).abs();
    Ok(OneSidedSlopeComparison {
        left,
        right,
        absolute_gap,
        scale,
        scaled_gap,
        tolerance,
        consistent: scaled_gap <= tolerance,
    })
}

/// Runs a central difference and compares it with one analytic candidate.
///
/// The objective has the same smoothness, determinism, and side-effect
/// requirements as [`central_difference`].
pub fn scalar_gradient_check(
    point: f64,
    analytic: f64,
    step: f64,
    tolerance: f64,
    evaluate: impl FnMut(f64) -> f64,
) -> Result<ScalarGradientCheck, GradCheckError> {
    validate_tolerance(tolerance)?;
    let difference = central_difference(point, step, evaluate)?;
    let comparison = compare_gradients(analytic, difference.derivative, tolerance)?;
    Ok(ScalarGradientCheck {
        difference,
        comparison,
    })
}
// endregion:scale-aware-comparison

/// One deterministic row-major coordinate selected for checking.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct SampledCoordinate {
    pub flat_index: usize,
    pub coordinate: Vec<usize>,
}

/// A checked numerical derivative at one tensor coordinate.
#[derive(Clone, Debug, PartialEq)]
pub struct CoordinateGradientCheck {
    pub flat_index: usize,
    pub coordinate: Vec<usize>,
    pub difference: CentralDifference,
    pub comparison: GradientComparison,
}

/// The complete result of one deterministic sampled tensor check.
#[derive(Clone, Debug, PartialEq)]
pub struct TensorGradientCheck {
    pub shape: Vec<usize>,
    pub requested_samples: usize,
    pub checks: Vec<CoordinateGradientCheck>,
    pub passed: bool,
}

fn element_count(shape: &[usize]) -> Result<usize, GradCheckError> {
    shape.iter().rev().try_fold(1_usize, |count, &dimension| {
        count
            .checked_mul(dimension)
            .ok_or(GradCheckError::ShapeOverflow)
    })
}

fn coordinate_from_offset(
    shape: &[usize],
    mut flat_index: usize,
) -> Result<Vec<usize>, GradCheckError> {
    let mut coordinate = Vec::new();
    coordinate.try_reserve_exact(shape.len()).map_err(|_| {
        GradCheckError::SampleAllocationFailed {
            samples: 1,
            rank: shape.len(),
        }
    })?;
    coordinate.resize(shape.len(), 0);
    for axis in (0..shape.len()).rev() {
        coordinate[axis] = flat_index % shape[axis];
        flat_index /= shape[axis];
    }
    Ok(coordinate)
}

// region:sample-tensor-coordinates
/// Selects unique, ordered coordinates without randomness or hidden state.
pub fn sample_tensor_coordinates(
    shape: &[usize],
    max_samples: usize,
) -> Result<Vec<SampledCoordinate>, GradCheckError> {
    if max_samples == 0 {
        return Err(GradCheckError::ZeroSamples);
    }
    let elements = element_count(shape)?;
    if elements == 0 {
        return Err(GradCheckError::EmptyTensor);
    }
    let samples = max_samples.min(elements);
    let mut coordinates = Vec::new();
    coordinates
        .try_reserve_exact(samples)
        .map_err(|_| GradCheckError::SampleAllocationFailed {
            samples,
            rank: shape.len(),
        })?;

    for sample in 0..samples {
        let flat_index = if samples == 1 {
            elements / 2
        } else {
            let numerator = (sample as u128) * ((elements - 1) as u128);
            (numerator / ((samples - 1) as u128)) as usize
        };
        coordinates.push(SampledCoordinate {
            flat_index,
            coordinate: coordinate_from_offset(shape, flat_index)?,
        });
    }
    Ok(coordinates)
}
// endregion:sample-tensor-coordinates

fn at_coordinate(coordinate: &[usize], source: GradCheckError) -> GradCheckError {
    GradCheckError::AtCoordinate {
        coordinate: coordinate.to_vec(),
        source: Box::new(source),
    }
}

// region:sampled-tensor-gradient-check
/// Checks deterministic tensor coordinates while restoring every probed value.
///
/// The parameter tensor is restored on every ordinary `Ok` or `Err` path. A
/// panic inside `objective` is deliberately outside this reference guarantee.
/// The objective must be deterministic, side-effect-free, and differentiable
/// with sufficient smoothness across every sampled probe interval; known or
/// possible kinks are outside this comparison's contract.
pub fn sampled_tensor_gradient_check(
    parameters: &mut Tensor,
    analytic: &TensorView<'_>,
    step: f64,
    tolerance: f64,
    max_samples: usize,
    mut objective: impl FnMut(&Tensor) -> f64,
) -> Result<TensorGradientCheck, GradCheckError> {
    validate_step(step)?;
    validate_tolerance(tolerance)?;
    if parameters.shape() != analytic.shape() {
        return Err(GradCheckError::GradientShapeMismatch {
            parameters: parameters.shape().to_vec(),
            analytic: analytic.shape().to_vec(),
        });
    }

    let samples = sample_tensor_coordinates(parameters.shape(), max_samples)?;
    let mut candidates = Vec::new();
    candidates.try_reserve_exact(samples.len()).map_err(|_| {
        GradCheckError::SampleAllocationFailed {
            samples: samples.len(),
            rank: parameters.rank(),
        }
    })?;

    // Validate every selected coordinate before the first objective call.
    for sample in &samples {
        let point = parameters.as_slice()[sample.flat_index];
        perturbations(point, step).map_err(|error| at_coordinate(&sample.coordinate, error))?;
        let analytic_value = *analytic
            .get(&sample.coordinate)
            .map_err(GradCheckError::View)?;
        if !analytic_value.is_finite() {
            return Err(at_coordinate(
                &sample.coordinate,
                GradCheckError::NonFiniteAnalyticGradient {
                    value: analytic_value,
                },
            ));
        }
        candidates.push((sample.clone(), point, analytic_value));
    }

    let mut checks = Vec::new();
    checks.try_reserve_exact(candidates.len()).map_err(|_| {
        GradCheckError::SampleAllocationFailed {
            samples: candidates.len(),
            rank: parameters.rank(),
        }
    })?;

    for (sample, point, analytic_value) in candidates {
        let difference = central_difference(point, step, |probe| {
            parameters.as_mut_slice()[sample.flat_index] = probe;
            let value = objective(parameters);
            parameters.as_mut_slice()[sample.flat_index] = point;
            value
        })
        .map_err(|error| at_coordinate(&sample.coordinate, error))?;
        let comparison = compare_gradients(analytic_value, difference.derivative, tolerance)
            .map_err(|error| at_coordinate(&sample.coordinate, error))?;
        checks.push(CoordinateGradientCheck {
            flat_index: sample.flat_index,
            coordinate: sample.coordinate,
            difference,
            comparison,
        });
    }

    Ok(TensorGradientCheck {
        shape: parameters.shape().to_vec(),
        requested_samples: max_samples,
        passed: checks.iter().all(|check| check.comparison.passed),
        checks,
    })
}
// endregion:sampled-tensor-gradient-check

#[cfg(test)]
mod tests {
    use super::*;
    use crate::nn::probability::indexed_mean_nll;

    fn assert_close(actual: f64, expected: f64, tolerance: f64) {
        assert!(
            (actual - expected).abs() <= tolerance,
            "expected {expected:?}, got {actual:?}"
        );
    }

    #[test]
    fn central_difference_evaluates_minus_center_plus_and_records_actual_geometry() {
        let mut probes = Vec::new();
        let difference = central_difference(3.0, 0.1, |point| {
            probes.push(point);
            point * point
        })
        .unwrap();

        assert_eq!(probes, [2.9, 3.0, 3.1]);
        assert_eq!(difference.requested_step, 0.1);
        assert_eq!(difference.minus_spacing, 3.0 - 2.9);
        assert_eq!(difference.plus_spacing, 3.1 - 3.0);
        assert_eq!(difference.stencil, DifferenceStencil::Symmetric);
        assert_close(difference.derivative, 6.0, 1.0e-12);
        assert_eq!(difference.minus_value, 2.9 * 2.9);
        assert_eq!(difference.center_value, 3.0 * 3.0);
        assert_eq!(difference.plus_value, 3.1 * 3.1);
    }

    #[test]
    fn rounded_unequal_probes_use_actual_three_point_weights() {
        let point = 1.0;
        let requested_step = 0.6 * f64::EPSILON;
        let identity = central_difference(point, requested_step, |value| value).unwrap();

        assert_eq!(identity.minus_point, f64::from_bits(point.to_bits() - 1));
        assert_eq!(identity.plus_point, f64::from_bits(point.to_bits() + 1));
        assert_eq!(identity.minus_spacing, f64::EPSILON / 2.0);
        assert_eq!(identity.plus_spacing, f64::EPSILON);
        assert_eq!(identity.stencil, DifferenceStencil::Unequal);
        assert_close(identity.left_weight, 2.0 / 3.0, 0.0);
        assert_close(identity.right_weight, 1.0 / 3.0, 0.0);
        assert_eq!(identity.left_slope, 1.0);
        assert_eq!(identity.right_slope, 1.0);
        assert_close(identity.derivative, 1.0, f64::EPSILON);

        let requested_denominator =
            (identity.plus_value - identity.minus_value) / (2.0 * requested_step);
        assert_eq!(requested_denominator, 1.25);

        let centered_square = central_difference(point, requested_step, |value| {
            let centered = value - point;
            centered * centered
        })
        .unwrap();
        assert_eq!(centered_square.stencil, DifferenceStencil::Unequal);
        assert_close(centered_square.derivative, 0.0, f64::EPSILON);
    }

    #[test]
    fn scaled_weights_do_not_require_the_actual_spacing_sum_to_be_finite() {
        let difference = central_difference(0.0, f64::MAX, |value| value).unwrap();
        assert_eq!(difference.minus_spacing, f64::MAX);
        assert_eq!(difference.plus_spacing, f64::MAX);
        assert!(!(difference.minus_spacing + difference.plus_spacing).is_finite());
        assert_eq!(difference.left_weight, 0.5);
        assert_eq!(difference.right_weight, 0.5);
        assert_eq!(difference.derivative, 1.0);
    }

    #[test]
    fn one_sided_diagnostic_exposes_a_centered_false_pass_at_a_kink() {
        let kink = central_difference(0.0, 0.1, f64::abs).unwrap();
        let diagnostic = compare_one_sided_slopes(&kink, 1.0e-12).unwrap();

        assert_eq!(kink.derivative, 0.0);
        assert_eq!(diagnostic.left, -1.0);
        assert_eq!(diagnostic.right, 1.0);
        assert_eq!(diagnostic.scaled_gap, 2.0);
        assert!(!diagnostic.consistent);

        let smooth = central_difference(1.0, 0.6 * f64::EPSILON, |value| value).unwrap();
        assert!(
            compare_one_sided_slopes(&smooth, f64::EPSILON)
                .unwrap()
                .consistent
        );
        assert!(matches!(
            compare_one_sided_slopes(&smooth, f64::NAN),
            Err(GradCheckError::InvalidTolerance { .. })
        ));
        let mut nonfinite_left = smooth;
        nonfinite_left.left_slope = f64::NAN;
        assert!(matches!(
            compare_one_sided_slopes(&nonfinite_left, 0.0),
            Err(GradCheckError::NonFiniteOneSidedSlope {
                side: DifferenceSide::Minus,
                ..
            })
        ));
        let mut nonfinite_right = smooth;
        nonfinite_right.right_slope = f64::INFINITY;
        assert!(matches!(
            compare_one_sided_slopes(&nonfinite_right, 0.0),
            Err(GradCheckError::NonFiniteOneSidedSlope {
                side: DifferenceSide::Plus,
                ..
            })
        ));
    }

    #[test]
    fn composed_function_matches_its_analytic_derivative() {
        let point = 0.7_f64;
        let analytic = point.exp() * (point.sin() + point.cos());
        let check = scalar_gradient_check(point, analytic, 1.0e-5, 1.0e-9, |value| {
            value.exp() * value.sin()
        })
        .unwrap();

        assert!(check.comparison.passed);
        assert!(check.comparison.scaled_error < 1.0e-9);
    }

    #[test]
    fn comparison_rejects_wrong_gradients_and_respects_scale() {
        let wrong = compare_gradients(5.5, 6.0, 1.0e-6).unwrap();
        assert!(!wrong.passed);
        assert_close(wrong.scale, 6.0, 0.0);
        assert_close(wrong.scaled_error, 1.0 / 12.0, 1.0e-15);

        let large = compare_gradients(1.0e12, 1.0e12 + 1.0e4, 1.1e-8).unwrap();
        assert!(large.passed);
        assert_eq!(
            compare_gradients(f64::MAX, -f64::MAX, 1.9)
                .unwrap()
                .scaled_error,
            2.0
        );
    }

    #[test]
    fn deterministic_samples_span_the_tensor() {
        let samples = sample_tensor_coordinates(&[2, 3], 4).unwrap();
        assert_eq!(
            samples,
            [
                SampledCoordinate {
                    flat_index: 0,
                    coordinate: vec![0, 0],
                },
                SampledCoordinate {
                    flat_index: 1,
                    coordinate: vec![0, 1],
                },
                SampledCoordinate {
                    flat_index: 3,
                    coordinate: vec![1, 0],
                },
                SampledCoordinate {
                    flat_index: 5,
                    coordinate: vec![1, 2],
                },
            ]
        );
        assert_eq!(
            sample_tensor_coordinates(&[2, 3], 1).unwrap(),
            [SampledCoordinate {
                flat_index: 3,
                coordinate: vec![1, 0],
            }]
        );
        assert_eq!(
            sample_tensor_coordinates(&[], 9).unwrap(),
            [SampledCoordinate {
                flat_index: 0,
                coordinate: vec![],
            }]
        );
    }

    fn tiny_logits() -> Tensor {
        Tensor::from_vec(vec![2, 3], vec![0.0, 1.0, -1.0, 2.0, 0.0, -2.0]).unwrap()
    }

    fn frozen_analytic_nll_gradient() -> Tensor {
        // Independent precomputed values for the fixed logits and targets. The
        // numerical objective below is the production indexed-NLL path.
        Tensor::from_vec(
            vec![2, 3],
            vec![
                -0.377_635_764_472_601_2,
                0.332_620_477_887_410_9,
                0.045_015_286_585_190_23,
                0.433_406_666_098_667_45,
                0.058_655_213_913_099_18,
                -0.492_061_880_011_766_6,
            ],
        )
        .unwrap()
    }

    #[test]
    fn sampled_logits_match_hand_derived_nll_gradient() {
        let mut logits = tiny_logits();
        let original_bits = logits
            .as_slice()
            .iter()
            .map(|value| value.to_bits())
            .collect::<Vec<_>>();
        let analytic = frozen_analytic_nll_gradient();
        let check = sampled_tensor_gradient_check(
            &mut logits,
            &analytic.view(),
            1.0e-5,
            1.0e-6,
            4,
            |candidate| indexed_mean_nll(&candidate.view(), 1, &[0, 2]).unwrap(),
        )
        .unwrap();

        assert!(check.passed);
        assert_eq!(
            check
                .checks
                .iter()
                .map(|check| check.flat_index)
                .collect::<Vec<_>>(),
            [0, 1, 3, 5]
        );
        assert!(
            check
                .checks
                .iter()
                .all(|check| check.comparison.scaled_error < 1.0e-9)
        );
        assert_eq!(
            logits
                .as_slice()
                .iter()
                .map(|value| value.to_bits())
                .collect::<Vec<_>>(),
            original_bits
        );

        let mut corrupted_values = analytic.as_slice().to_vec();
        corrupted_values[0] += 0.25;
        corrupted_values[5] -= 0.25;
        let corrupted = Tensor::from_vec(vec![2, 3], corrupted_values).unwrap();
        let corrupted_check = sampled_tensor_gradient_check(
            &mut logits,
            &corrupted.view(),
            1.0e-5,
            1.0e-6,
            4,
            |candidate| indexed_mean_nll(&candidate.view(), 1, &[0, 2]).unwrap(),
        )
        .unwrap();
        assert!(!corrupted_check.passed);
        assert_eq!(
            logits
                .as_slice()
                .iter()
                .map(|value| value.to_bits())
                .collect::<Vec<_>>(),
            original_bits
        );
    }

    #[test]
    fn tensor_is_restored_after_failed_comparison_and_error() {
        let mut parameters = Tensor::from_vec(vec![2], vec![-0.0, 2.0]).unwrap();
        let original_bits = parameters
            .as_slice()
            .iter()
            .map(|value| value.to_bits())
            .collect::<Vec<_>>();
        let wrong = Tensor::from_vec(vec![2], vec![99.0, 99.0]).unwrap();
        let check = sampled_tensor_gradient_check(
            &mut parameters,
            &wrong.view(),
            1.0e-5,
            1.0e-8,
            2,
            |tensor| tensor.as_slice().iter().map(|value| value * value).sum(),
        )
        .unwrap();
        assert!(!check.passed);
        assert_eq!(
            parameters
                .as_slice()
                .iter()
                .map(|value| value.to_bits())
                .collect::<Vec<_>>(),
            original_bits
        );

        let error = sampled_tensor_gradient_check(
            &mut parameters,
            &wrong.view(),
            1.0e-5,
            1.0e-8,
            2,
            |_| f64::NAN,
        )
        .unwrap_err();
        assert!(matches!(
            error,
            GradCheckError::AtCoordinate {
                source,
                ..
            } if matches!(*source, GradCheckError::NonFiniteEvaluation {
                side: DifferenceSide::Minus,
                ..
            })
        ));
        assert_eq!(
            parameters
                .as_slice()
                .iter()
                .map(|value| value.to_bits())
                .collect::<Vec<_>>(),
            original_bits
        );

        let mut calls = 0;
        let center_error = sampled_tensor_gradient_check(
            &mut parameters,
            &wrong.view(),
            1.0e-5,
            1.0e-8,
            2,
            |_| {
                calls += 1;
                if calls == 2 { f64::NAN } else { 0.0 }
            },
        )
        .unwrap_err();
        assert!(matches!(
            center_error,
            GradCheckError::AtCoordinate {
                source,
                ..
            } if matches!(*source, GradCheckError::NonFiniteEvaluation {
                side: DifferenceSide::Center,
                ..
            })
        ));
        assert_eq!(calls, 2);
        assert_eq!(
            parameters
                .as_slice()
                .iter()
                .map(|value| value.to_bits())
                .collect::<Vec<_>>(),
            original_bits
        );

        calls = 0;
        let plus_error = sampled_tensor_gradient_check(
            &mut parameters,
            &wrong.view(),
            1.0e-5,
            1.0e-8,
            2,
            |_| {
                calls += 1;
                if calls == 3 { f64::NAN } else { 0.0 }
            },
        )
        .unwrap_err();
        assert!(matches!(
            plus_error,
            GradCheckError::AtCoordinate {
                source,
                ..
            } if matches!(*source, GradCheckError::NonFiniteEvaluation {
                side: DifferenceSide::Plus,
                ..
            })
        ));
        assert_eq!(calls, 3);
        assert_eq!(
            parameters
                .as_slice()
                .iter()
                .map(|value| value.to_bits())
                .collect::<Vec<_>>(),
            original_bits
        );
    }

    #[test]
    fn tensor_objective_observes_minus_center_plus_and_every_probe_is_restored() {
        let mut parameters = Tensor::from_vec(vec![1], vec![1.0]).unwrap();
        let analytic = Tensor::from_vec(vec![1], vec![1.0]).unwrap();
        let original_bits = parameters.as_slice()[0].to_bits();
        let mut probes = Vec::new();
        let check = sampled_tensor_gradient_check(
            &mut parameters,
            &analytic.view(),
            0.6 * f64::EPSILON,
            f64::EPSILON,
            1,
            |tensor| {
                probes.push(tensor.as_slice()[0]);
                tensor.as_slice()[0]
            },
        )
        .unwrap();

        let difference = check.checks[0].difference;
        assert_eq!(
            probes,
            [
                difference.minus_point,
                difference.point,
                difference.plus_point
            ]
        );
        assert!(check.passed);
        assert_eq!(parameters.as_slice()[0].to_bits(), original_bits);
    }

    #[test]
    fn invalid_requests_fail_before_objective_calls() {
        let mut calls = 0;
        assert!(matches!(
            central_difference(1.0, 0.0, |_| {
                calls += 1;
                0.0
            }),
            Err(GradCheckError::InvalidStep { .. })
        ));
        assert!(matches!(
            central_difference(1.0, 1.0e-20, |_| 0.0),
            Err(GradCheckError::PerturbationUnchanged {
                side: DifferenceSide::Minus,
                ..
            })
        ));
        assert!(matches!(
            compare_gradients(1.0, 1.0, f64::NAN),
            Err(GradCheckError::InvalidTolerance { .. })
        ));
        for step in [-1.0, f64::NAN, f64::INFINITY] {
            assert!(matches!(
                central_difference(1.0, step, |_| 0.0),
                Err(GradCheckError::InvalidStep { .. })
            ));
        }
        assert!(matches!(
            central_difference(f64::INFINITY, 0.1, |_| 0.0),
            Err(GradCheckError::NonFinitePoint { .. })
        ));
        assert!(matches!(
            central_difference(f64::MAX, f64::MAX / 2.0, |_| 0.0),
            Err(GradCheckError::PerturbationNotFinite {
                side: DifferenceSide::Plus,
                ..
            })
        ));
        assert!(matches!(
            central_difference(0.0, 0.1, |point| {
                if point.is_sign_negative() {
                    -f64::MAX
                } else {
                    f64::MAX
                }
            }),
            Err(GradCheckError::NonFiniteOneSidedSlope {
                side: DifferenceSide::Minus,
                ..
            })
        ));
        for tolerance in [-1.0, f64::INFINITY] {
            assert!(matches!(
                compare_gradients(1.0, 1.0, tolerance),
                Err(GradCheckError::InvalidTolerance { .. })
            ));
        }
        assert!(matches!(
            compare_gradients(f64::NAN, 1.0, 0.0),
            Err(GradCheckError::NonFiniteAnalyticGradient { .. })
        ));

        let mut parameters = tiny_logits();
        let wrong_shape = Tensor::from_vec(vec![6], vec![0.0; 6]).unwrap();
        assert!(matches!(
            sampled_tensor_gradient_check(
                &mut parameters,
                &wrong_shape.view(),
                1.0e-5,
                1.0e-6,
                4,
                |_| {
                    calls += 1;
                    0.0
                }
            ),
            Err(GradCheckError::GradientShapeMismatch { .. })
        ));
        assert_eq!(calls, 0);
        let mut nonfinite_parameters = Tensor::from_vec(vec![2], vec![1.0, f64::NAN]).unwrap();
        let finite_analytic = Tensor::from_vec(vec![2], vec![1.0, 1.0]).unwrap();
        let parameter_error = sampled_tensor_gradient_check(
            &mut nonfinite_parameters,
            &finite_analytic.view(),
            1.0e-5,
            1.0e-6,
            2,
            |_| {
                calls += 1;
                0.0
            },
        )
        .unwrap_err();
        assert!(matches!(
            parameter_error,
            GradCheckError::AtCoordinate {
                coordinate,
                source,
            } if coordinate == [1]
                && matches!(*source, GradCheckError::NonFinitePoint { .. })
        ));
        assert_eq!(calls, 0);

        let mut finite_parameters = Tensor::from_vec(vec![2], vec![1.0, 2.0]).unwrap();
        let nonfinite_analytic = Tensor::from_vec(vec![2], vec![f64::NAN, 1.0]).unwrap();
        let analytic_error = sampled_tensor_gradient_check(
            &mut finite_parameters,
            &nonfinite_analytic.view(),
            1.0e-5,
            1.0e-6,
            2,
            |_| {
                calls += 1;
                0.0
            },
        )
        .unwrap_err();
        assert!(matches!(
            analytic_error,
            GradCheckError::AtCoordinate {
                coordinate,
                source,
            } if coordinate == [0]
                && matches!(*source, GradCheckError::NonFiniteAnalyticGradient { .. })
        ));
        assert_eq!(calls, 0);
        assert_eq!(
            sample_tensor_coordinates(&[2, 0, 3], 1),
            Err(GradCheckError::EmptyTensor)
        );
        assert_eq!(
            sample_tensor_coordinates(&[usize::MAX, 2, 0], 1),
            Err(GradCheckError::EmptyTensor)
        );
        assert_eq!(
            sample_tensor_coordinates(&[usize::MAX, 2], 1),
            Err(GradCheckError::ShapeOverflow)
        );
        assert_eq!(
            sample_tensor_coordinates(&[0, usize::MAX, 2], 1),
            Err(GradCheckError::ShapeOverflow)
        );
        assert_eq!(
            sample_tensor_coordinates(&[2, 3], 0),
            Err(GradCheckError::ZeroSamples)
        );
    }
}

//! Model-critical tensor operations and their local reverse-mode rules.

use std::error::Error;
use std::fmt;

use super::tensor_core::{
    AutogradContext, TensorAutodiffError, TensorOperation, TensorValue, accumulate_unbroadcast,
};
use crate::nn::probability::{indexed_mean_nll_forward, log_softmax_forward};
use crate::tensor::matmul::{matmul, matmul_with_transpose};
use crate::tensor::ops::{map_binary, map_unary, sum_axis as tensor_sum_axis};
use crate::tensor::storage::{Tensor, checked_row_major_layout};

// region:model-op-errors
/// A rejected model-specific shape, selector, or allocation.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ModelOpError {
    GatherTableRank {
        rank: usize,
    },
    GatherIndexCountMismatch {
        expected: usize,
        actual: usize,
    },
    GatherIndexOutOfBounds {
        position: usize,
        index: usize,
        rows: usize,
    },
    CausalSoftmaxRank {
        rank: usize,
    },
    CausalSoftmaxNonSquare {
        queries: usize,
        keys: usize,
    },
    CausalSoftmaxEmptyTokens,
    OutputAllocationFailed {
        elements: usize,
    },
}

impl fmt::Display for ModelOpError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::GatherTableRank { rank } => {
                write!(
                    formatter,
                    "row gather needs a rank-two table, got rank {rank}"
                )
            }
            Self::GatherIndexCountMismatch { expected, actual } => write!(
                formatter,
                "gather index shape needs {expected} IDs, but received {actual}"
            ),
            Self::GatherIndexOutOfBounds {
                position,
                index,
                rows,
            } => write!(
                formatter,
                "gather ID {index} at flat position {position} is out of bounds for {rows} rows"
            ),
            Self::CausalSoftmaxRank { rank } => write!(
                formatter,
                "causal softmax needs at least rank-two [..., queries, keys] scores, got rank {rank}"
            ),
            Self::CausalSoftmaxNonSquare { queries, keys } => write!(
                formatter,
                "causal softmax needs a square query-key grid, got {queries} queries and {keys} keys"
            ),
            Self::CausalSoftmaxEmptyTokens => formatter.write_str(
                "causal softmax needs at least one token so every row has an allowed key",
            ),
            Self::OutputAllocationFailed { elements } => write!(
                formatter,
                "cannot allocate model-operation output for {elements} f64 values"
            ),
        }
    }
}

impl Error for ModelOpError {}
// endregion:model-op-errors

// region:model-saved-context
/// Immutable forward evidence used by one model-operation parent edge.
#[derive(Clone, Debug, PartialEq)]
pub enum ModelSavedContext {
    MatmulLeft {
        right: Tensor,
        input_shape: Vec<usize>,
        output_shape: Vec<usize>,
    },
    MatmulRight {
        left: Tensor,
        input_shape: Vec<usize>,
        output_shape: Vec<usize>,
    },
    GatherRows {
        indices: Vec<usize>,
        index_shape: Vec<usize>,
        input_shape: Vec<usize>,
        output_shape: Vec<usize>,
    },
    Exp {
        output: Tensor,
    },
    Log {
        input: Tensor,
    },
    Silu {
        input: Tensor,
        sigmoid: Tensor,
    },
    LogSoftmax {
        probabilities: Tensor,
        axis: usize,
        input_shape: Vec<usize>,
    },
    CausalSoftmax {
        probabilities: Tensor,
        input_shape: Vec<usize>,
        tokens: usize,
    },
    RotaryPairs {
        cosines: Tensor,
        sines: Tensor,
        input_shape: Vec<usize>,
    },
    IndexedMeanNll {
        probabilities: Tensor,
        targets: Vec<usize>,
        axis: usize,
        input_shape: Vec<usize>,
        groups: usize,
    },
}
// endregion:model-saved-context

// region:model-row-gather-plan
/// Owned row-gather facts established before materialization begins.
#[derive(Debug)]
pub(crate) struct RowGatherPlan {
    indices: Vec<usize>,
    index_shape: Vec<usize>,
    input_shape: [usize; 2],
    output_shape: Vec<usize>,
    output_len: usize,
}

impl RowGatherPlan {
    fn checked(
        table: &Tensor,
        indices: &[usize],
        index_shape: &[usize],
    ) -> Result<Self, TensorAutodiffError> {
        if table.rank() != 2 {
            return Err(ModelOpError::GatherTableRank { rank: table.rank() }.into());
        }
        let (_, expected) = checked_row_major_layout(index_shape)?;
        if indices.len() != expected {
            return Err(ModelOpError::GatherIndexCountMismatch {
                expected,
                actual: indices.len(),
            }
            .into());
        }
        let rows = table.shape()[0];
        for (position, &index) in indices.iter().enumerate() {
            if index >= rows {
                return Err(ModelOpError::GatherIndexOutOfBounds {
                    position,
                    index,
                    rows,
                }
                .into());
            }
        }

        Self::from_validated_indices(table, indices.to_vec(), index_shape.to_vec())
    }

    /// Seals indices whose shape, count, and bounds were established by a
    /// crate-owned caller for this exact rank-two table.
    pub(crate) fn from_validated_indices(
        table: &Tensor,
        indices: Vec<usize>,
        index_shape: Vec<usize>,
    ) -> Result<Self, TensorAutodiffError> {
        let input_shape = [table.shape()[0], table.shape()[1]];
        let width = input_shape[1];
        let mut output_shape = index_shape.clone();
        output_shape
            .try_reserve_exact(1)
            .map_err(|_| ModelOpError::OutputAllocationFailed {
                elements: indices.len().saturating_mul(width),
            })?;
        output_shape.push(width);
        let (_, output_len) = checked_row_major_layout(&output_shape)?;
        Ok(Self {
            indices,
            index_shape,
            input_shape,
            output_shape,
            output_len,
        })
    }

    fn into_saved_context(self) -> ModelSavedContext {
        let Self {
            indices,
            index_shape,
            input_shape,
            output_shape,
            ..
        } = self;
        ModelSavedContext::GatherRows {
            indices,
            index_shape,
            input_shape: input_shape.to_vec(),
            output_shape,
        }
    }
}
// endregion:model-row-gather-plan

// region:model-autodiff-operations
impl TensorValue {
    /// Multiplies rank-two or batched tensors and records both matrix pullbacks.
    pub fn matmul(&self, right: &Self) -> Result<Self, TensorAutodiffError> {
        self.matmul_with_context(AutogradContext::recording(), right)
    }

    /// Multiplies tensors under the caller's explicit graph-recording policy.
    pub fn matmul_with_context(
        &self,
        context: AutogradContext,
        right: &Self,
    ) -> Result<Self, TensorAutodiffError> {
        Self::model_operation_with_context(
            context,
            TensorOperation::MatMul,
            [self, right],
            |primals| {
                let left = primals[0];
                let right = primals[1];
                let value = matmul(&left.view(), &right.view())?;
                let output_shape = value.shape().to_vec();
                Ok((
                    value,
                    [
                        ModelSavedContext::MatmulLeft {
                            right: Tensor::clone(right),
                            input_shape: left.shape().to_vec(),
                            output_shape: output_shape.clone(),
                        },
                        ModelSavedContext::MatmulRight {
                            left: Tensor::clone(left),
                            input_shape: right.shape().to_vec(),
                            output_shape,
                        },
                    ],
                ))
            },
        )
    }

    // region:model-row-gather-operation
    /// Selects rows from a rank-two table into `index_shape + [width]`.
    ///
    /// IDs are integer selectors and are deliberately not tape operands.
    pub fn gather_rows(
        &self,
        indices: &[usize],
        index_shape: &[usize],
    ) -> Result<Self, TensorAutodiffError> {
        self.gather_rows_with_context(AutogradContext::recording(), indices, index_shape)
    }

    /// Selects rows under the caller's explicit graph-recording policy.
    pub fn gather_rows_with_context(
        &self,
        context: AutogradContext,
        indices: &[usize],
        index_shape: &[usize],
    ) -> Result<Self, TensorAutodiffError> {
        self.gather_rows_with_plan_and_context(context, |table| {
            RowGatherPlan::checked(table, indices, index_shape)
        })
    }

    /// Builds one row-gather plan under an explicit graph-recording policy.
    pub(crate) fn gather_rows_with_plan_and_context(
        &self,
        context: AutogradContext,
        build_plan: impl FnOnce(&Tensor) -> Result<RowGatherPlan, TensorAutodiffError>,
    ) -> Result<Self, TensorAutodiffError> {
        Self::model_operation_with_context(
            context,
            TensorOperation::GatherRows,
            [self],
            |primals| {
                let table = primals[0];
                let plan = build_plan(table)?;
                let value = gather_rows_forward(table, &plan)?;
                Ok((value, [plan.into_saved_context()]))
            },
        )
    }
    // endregion:model-row-gather-operation

    /// Applies the elementwise exponential and saves its output for reversal.
    pub fn exp(&self) -> Result<Self, TensorAutodiffError> {
        self.exp_with_context(AutogradContext::recording())
    }

    /// Applies the elementwise exponential under an explicit recording policy.
    pub fn exp_with_context(&self, context: AutogradContext) -> Result<Self, TensorAutodiffError> {
        Self::model_operation_with_context(context, TensorOperation::Exp, [self], |primals| {
            let value = map_unary(&primals[0].view(), f64::exp)?;
            Ok((value.clone(), [ModelSavedContext::Exp { output: value }]))
        })
    }

    /// Applies the natural logarithm; zero and negative inputs are rejected by
    /// the tape's finite-forward invariant.
    pub fn log(&self) -> Result<Self, TensorAutodiffError> {
        self.log_with_context(AutogradContext::recording())
    }

    /// Applies the natural logarithm under an explicit recording policy.
    pub fn log_with_context(&self, context: AutogradContext) -> Result<Self, TensorAutodiffError> {
        Self::model_operation_with_context(context, TensorOperation::Log, [self], |primals| {
            let input = primals[0];
            let value = map_unary(&input.view(), f64::ln)?;
            Ok((
                value,
                [ModelSavedContext::Log {
                    input: Tensor::clone(input),
                }],
            ))
        })
    }

    /// Applies SiLU, `x * sigmoid(x)`, with a branchwise stable sigmoid.
    pub fn silu(&self) -> Result<Self, TensorAutodiffError> {
        self.silu_with_context(AutogradContext::recording())
    }

    /// Applies SiLU under the caller's explicit graph-recording policy.
    pub fn silu_with_context(&self, context: AutogradContext) -> Result<Self, TensorAutodiffError> {
        Self::model_operation_with_context(context, TensorOperation::Silu, [self], |primals| {
            let input = primals[0];
            let sigmoid = map_unary(&input.view(), stable_sigmoid)?;
            let value = map_binary(&input.view(), &sigmoid.view(), |x, probability| {
                x * probability
            })?;
            Ok((
                value,
                [ModelSavedContext::Silu {
                    input: Tensor::clone(input),
                    sigmoid,
                }],
            ))
        })
    }

    // region:model-log-softmax-saved-forward
    /// Applies stable log-softmax along one explicit class axis.
    pub fn log_softmax(&self, axis: usize) -> Result<Self, TensorAutodiffError> {
        self.log_softmax_with_context(AutogradContext::recording(), axis)
    }

    /// Applies stable log-softmax under an explicit recording policy.
    pub fn log_softmax_with_context(
        &self,
        context: AutogradContext,
        axis: usize,
    ) -> Result<Self, TensorAutodiffError> {
        Self::model_operation_with_context(
            context,
            TensorOperation::LogSoftmax,
            [self],
            |primals| {
                let input = primals[0];
                let forward = log_softmax_forward(&input.view(), axis, true)?;
                let probabilities = forward
                    .probabilities
                    .expect("the autodiff log-softmax forward requests saved probabilities");
                Ok((
                    forward.value,
                    [ModelSavedContext::LogSoftmax {
                        probabilities,
                        axis,
                        input_shape: input.shape().to_vec(),
                    }],
                ))
            },
        )
    }
    // endregion:model-log-softmax-saved-forward

    /// Normalizes each square score row over its inclusive prefix of keys.
    ///
    /// Future-key probabilities are exactly zero. The implementation applies
    /// the additive negative-infinity mask as a branch, so non-finite values
    /// never enter the operation tape.
    pub fn causal_softmax(&self) -> Result<Self, TensorAutodiffError> {
        self.causal_softmax_with_context(AutogradContext::recording())
    }

    /// Applies causal softmax under an explicit graph-recording policy.
    pub fn causal_softmax_with_context(
        &self,
        context: AutogradContext,
    ) -> Result<Self, TensorAutodiffError> {
        Self::model_operation_with_context(
            context,
            TensorOperation::CausalSoftmax,
            [self],
            |primals| {
                let input = primals[0];
                let probabilities = causal_softmax_forward(input)?;
                let tokens = input.shape()[input.rank() - 1];
                Ok((
                    probabilities.clone(),
                    [ModelSavedContext::CausalSoftmax {
                        probabilities,
                        input_shape: input.shape().to_vec(),
                        tokens,
                    }],
                ))
            },
        )
    }

    /// Rotates adjacent feature pairs with one precomputed angle row per token.
    ///
    /// Shape and position-range validation belongs to the rotary-embedding
    /// owner. Keeping this primitive crate-private prevents callers from
    /// constructing inconsistent sine and cosine tables.
    /// Rotates feature pairs under an explicit graph-recording policy.
    pub(crate) fn rotary_pairs_with_context(
        &self,
        context: AutogradContext,
        cosines: &Tensor,
        sines: &Tensor,
    ) -> Result<Self, TensorAutodiffError> {
        let cosines = cosines.clone();
        let sines = sines.clone();
        Self::model_operation_with_context(
            context,
            TensorOperation::RotaryPairs,
            [self],
            move |primals| {
                let input = primals[0];
                let value = rotary_pairs_forward(input, &cosines, &sines, false)?;
                Ok((
                    value,
                    [ModelSavedContext::RotaryPairs {
                        cosines,
                        sines,
                        input_shape: input.shape().to_vec(),
                    }],
                ))
            },
        )
    }

    // region:model-indexed-nll-saved-forward
    /// Computes one stable rank-zero mean NLL from flat group-major targets.
    pub fn indexed_mean_nll(
        &self,
        axis: usize,
        targets: &[usize],
    ) -> Result<Self, TensorAutodiffError> {
        self.indexed_mean_nll_with_context(AutogradContext::recording(), axis, targets)
    }

    /// Computes indexed mean NLL under an explicit graph-recording policy.
    pub fn indexed_mean_nll_with_context(
        &self,
        context: AutogradContext,
        axis: usize,
        targets: &[usize],
    ) -> Result<Self, TensorAutodiffError> {
        Self::model_operation_with_context(
            context,
            TensorOperation::IndexedMeanNll,
            [self],
            |primals| {
                let logits = primals[0];
                let forward = indexed_mean_nll_forward(&logits.view(), axis, targets, true)?;
                let probabilities = forward
                    .probabilities
                    .expect("the autodiff indexed-NLL forward requests saved probabilities");
                let value = Tensor::from_vec(Vec::new(), vec![forward.loss])?;
                Ok((
                    value,
                    [ModelSavedContext::IndexedMeanNll {
                        probabilities,
                        targets: targets.to_vec(),
                        axis,
                        input_shape: logits.shape().to_vec(),
                        groups: targets.len(),
                    }],
                ))
            },
        )
    }
    // endregion:model-indexed-nll-saved-forward
}
// endregion:model-autodiff-operations

fn stable_sigmoid(value: f64) -> f64 {
    if value >= 0.0 {
        1.0 / (1.0 + (-value).exp())
    } else {
        let exponential = value.exp();
        exponential / (1.0 + exponential)
    }
}

fn output_buffer(elements: usize) -> Result<Vec<f64>, TensorAutodiffError> {
    let mut values = Vec::new();
    values
        .try_reserve_exact(elements)
        .map_err(|_| ModelOpError::OutputAllocationFailed { elements })?;
    values.resize(elements, 0.0);
    Ok(values)
}

fn zeros(shape: &[usize]) -> Result<Tensor, TensorAutodiffError> {
    let (_, elements) = checked_row_major_layout(shape)?;
    Tensor::from_vec(shape.to_vec(), output_buffer(elements)?).map_err(Into::into)
}

fn gather_rows_forward(
    table: &Tensor,
    plan: &RowGatherPlan,
) -> Result<Tensor, TensorAutodiffError> {
    debug_assert_eq!(table.shape(), plan.input_shape);
    let width = plan.input_shape[1];
    let mut values = output_buffer(plan.output_len)?;
    for (position, &index) in plan.indices.iter().enumerate() {
        let source = index * width;
        let destination = position * width;
        values[destination..destination + width]
            .copy_from_slice(&table.as_slice()[source..source + width]);
    }
    Tensor::from_vec(plan.output_shape.clone(), values).map_err(Into::into)
}

// region:causal-softmax-forward
fn causal_softmax_forward(input: &Tensor) -> Result<Tensor, TensorAutodiffError> {
    if input.rank() < 2 {
        return Err(ModelOpError::CausalSoftmaxRank { rank: input.rank() }.into());
    }
    let queries = input.shape()[input.rank() - 2];
    let keys = input.shape()[input.rank() - 1];
    if queries != keys {
        return Err(ModelOpError::CausalSoftmaxNonSquare { queries, keys }.into());
    }
    if queries == 0 {
        return Err(ModelOpError::CausalSoftmaxEmptyTokens.into());
    }

    let mut probabilities = zeros(input.shape())?;
    let grids = input.len() / (queries * keys);
    for grid in 0..grids {
        for query in 0..queries {
            let row_start = (grid * queries + query) * keys;
            let allowed = &input.as_slice()[row_start..=row_start + query];
            let maximum = allowed.iter().copied().fold(f64::NEG_INFINITY, f64::max);
            let mut exponential_tail = 0.0;
            let mut skipped_one_maximum = false;
            for &score in allowed {
                let shifted = score - maximum;
                if shifted == 0.0 && !skipped_one_maximum {
                    skipped_one_maximum = true;
                } else {
                    exponential_tail += shifted.exp();
                }
            }
            debug_assert!(skipped_one_maximum);
            let denominator = 1.0 + exponential_tail;
            for (key, &score) in allowed.iter().enumerate() {
                let probability = (score - maximum).exp() / denominator;
                probabilities.as_mut_slice()[row_start + key] =
                    if probability == 0.0 { 0.0 } else { probability };
            }
        }
    }
    Ok(probabilities)
}
// endregion:causal-softmax-forward

// region:rotary-pairs-forward
fn rotary_pairs_forward(
    input: &Tensor,
    cosines: &Tensor,
    sines: &Tensor,
    inverse: bool,
) -> Result<Tensor, TensorAutodiffError> {
    debug_assert!(input.rank() >= 2);
    debug_assert_eq!(cosines.shape(), sines.shape());
    debug_assert_eq!(cosines.rank(), 2);

    let width = input.shape()[input.rank() - 1];
    let tokens = input.shape()[input.rank() - 2];
    let pairs = width / 2;
    debug_assert_eq!(cosines.shape(), [tokens, pairs]);

    let mut output = zeros(input.shape())?;
    if input.is_empty() {
        return Ok(output);
    }

    let rows = input.len() / width;
    for row in 0..rows {
        let token = row % tokens;
        for pair in 0..pairs {
            let feature = row * width + pair * 2;
            let table = token * pairs + pair;
            let left = input.as_slice()[feature];
            let right = input.as_slice()[feature + 1];
            let cosine = cosines.as_slice()[table];
            let sine = sines.as_slice()[table];
            let (rotated_left, rotated_right) = if inverse {
                (left * cosine + right * sine, -left * sine + right * cosine)
            } else {
                (left * cosine - right * sine, left * sine + right * cosine)
            };
            output.as_mut_slice()[feature] = canonical_zero(rotated_left);
            output.as_mut_slice()[feature + 1] = canonical_zero(rotated_right);
        }
    }
    Ok(output)
}

fn canonical_zero(value: f64) -> f64 {
    if value == 0.0 { 0.0 } else { value }
}
// endregion:rotary-pairs-forward

// region:model-vjps
pub(crate) fn apply_model_vjp(
    upstream: &Tensor,
    saved: &ModelSavedContext,
) -> Result<Tensor, TensorAutodiffError> {
    match saved {
        ModelSavedContext::MatmulLeft {
            right,
            input_shape,
            output_shape,
        } => {
            debug_assert_eq!(upstream.shape(), output_shape);
            let expanded = matmul_with_transpose(&upstream.view(), &right.view(), false, true)?;
            unbroadcast(&expanded, input_shape)
        }
        ModelSavedContext::MatmulRight {
            left,
            input_shape,
            output_shape,
        } => {
            debug_assert_eq!(upstream.shape(), output_shape);
            let expanded = matmul_with_transpose(&left.view(), &upstream.view(), true, false)?;
            unbroadcast(&expanded, input_shape)
        }
        // region:model-row-gather-vjp
        ModelSavedContext::GatherRows {
            indices,
            input_shape,
            output_shape,
            ..
        } => {
            debug_assert_eq!(upstream.shape(), output_shape);
            let width = input_shape[1];
            let mut table_gradient = zeros(input_shape)?;
            for (position, &index) in indices.iter().enumerate() {
                let source = position * width;
                let destination = index * width;
                for feature in 0..width {
                    table_gradient.as_mut_slice()[destination + feature] +=
                        upstream.as_slice()[source + feature];
                }
            }
            Ok(table_gradient)
        }
        // endregion:model-row-gather-vjp
        ModelSavedContext::Exp { output } => {
            map_binary(&upstream.view(), &output.view(), |gradient, value| {
                gradient * value
            })
            .map_err(Into::into)
        }
        ModelSavedContext::Log { input } => {
            map_binary(&upstream.view(), &input.view(), |gradient, value| {
                gradient / value
            })
            .map_err(Into::into)
        }
        ModelSavedContext::Silu { input, sigmoid } => {
            let derivative = map_binary(&input.view(), &sigmoid.view(), |value, probability| {
                probability * (1.0 + value * (1.0 - probability))
            })?;
            map_binary(&upstream.view(), &derivative.view(), |gradient, local| {
                gradient * local
            })
            .map_err(Into::into)
        }
        ModelSavedContext::LogSoftmax {
            probabilities,
            axis,
            input_shape,
        } => {
            debug_assert_eq!(upstream.shape(), input_shape);
            let row_sum = tensor_sum_axis(&upstream.view(), *axis, true)?;
            let correction = map_binary(
                &probabilities.view(),
                &row_sum.view(),
                |probability, sum| probability * sum,
            )?;
            map_binary(&upstream.view(), &correction.view(), |gradient, term| {
                gradient - term
            })
            .map_err(Into::into)
        }
        ModelSavedContext::CausalSoftmax {
            probabilities,
            input_shape,
            tokens,
        } => {
            debug_assert_eq!(upstream.shape(), input_shape);
            let tokens = *tokens;
            let mut result = zeros(input_shape)?;
            let grids = upstream.len() / (tokens * tokens);
            for grid in 0..grids {
                for query in 0..tokens {
                    let row_start = (grid * tokens + query) * tokens;
                    let mut weighted_upstream = 0.0;
                    for key in 0..=query {
                        weighted_upstream += upstream.as_slice()[row_start + key]
                            * probabilities.as_slice()[row_start + key];
                    }
                    for key in 0..=query {
                        let offset = row_start + key;
                        let gradient = probabilities.as_slice()[offset]
                            * (upstream.as_slice()[offset] - weighted_upstream);
                        result.as_mut_slice()[offset] =
                            if gradient == 0.0 { 0.0 } else { gradient };
                    }
                }
            }
            Ok(result)
        }
        ModelSavedContext::RotaryPairs {
            cosines,
            sines,
            input_shape,
        } => {
            debug_assert_eq!(upstream.shape(), input_shape);
            rotary_pairs_forward(upstream, cosines, sines, true)
        }
        ModelSavedContext::IndexedMeanNll {
            probabilities,
            targets,
            axis,
            input_shape,
            groups,
        } => {
            debug_assert_eq!(upstream.shape(), &[] as &[usize]);
            debug_assert_eq!(probabilities.shape(), input_shape);
            debug_assert_eq!(targets.len(), *groups);
            debug_assert!(targets.iter().all(|&target| target < input_shape[*axis]));
            let mut result = probabilities.clone();

            let mut group_shape = input_shape.to_vec();
            let mut group_strides = result.strides().to_vec();
            group_shape.remove(*axis);
            let class_stride = group_strides.remove(*axis);
            let group_offsets = result
                .view()
                .projected_offsets(&group_shape, &group_strides, *groups)
                .expect("a checked indexed-NLL VJP retains valid group offsets");

            for (group_offset, &target) in group_offsets.zip(targets) {
                let target_offset = target
                    .checked_mul(class_stride)
                    .and_then(|class_offset| group_offset.checked_add(class_offset))
                    .expect("a checked indexed-NLL target retains a valid storage offset");
                result.as_mut_slice()[target_offset] -= 1.0;
            }
            let scale = upstream.as_slice()[0] / (*groups as f64);
            for value in result.as_mut_slice() {
                *value *= scale;
                if *value == 0.0 {
                    *value = 0.0;
                }
            }
            Ok(result)
        }
    }
}
// endregion:model-vjps

fn unbroadcast(upstream: &Tensor, input_shape: &[usize]) -> Result<Tensor, TensorAutodiffError> {
    let mut result = zeros(input_shape)?;
    accumulate_unbroadcast(upstream, &mut result);
    Ok(result)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::autograd::gradcheck::sampled_tensor_gradient_check;
    use crate::autograd::tensor_core::{GraphRetention, TensorSavedContext};
    use crate::nn::probability::{ProbabilityError, indexed_mean_nll, log_softmax, softmax};
    use crate::tensor::matmul::matmul as tensor_matmul;

    const STEP: f64 = 1e-6;
    const TOLERANCE: f64 = 2e-6;

    fn tensor(shape: &[usize], values: &[f64]) -> Tensor {
        Tensor::from_vec(shape.to_vec(), values.to_vec()).unwrap()
    }

    fn parameter(shape: &[usize], values: &[f64]) -> TensorValue {
        TensorValue::parameter(tensor(shape, values)).unwrap()
    }

    fn constant(shape: &[usize], values: &[f64]) -> TensorValue {
        TensorValue::constant(tensor(shape, values)).unwrap()
    }

    fn sum_to_scalar(mut value: TensorValue) -> TensorValue {
        while !value.shape().is_empty() {
            value = value.sum_axis(0, false).unwrap();
        }
        value
    }

    fn assert_close(actual: &[f64], expected: &[f64], tolerance: f64) {
        assert_eq!(actual.len(), expected.len());
        for (index, (&actual, &expected)) in actual.iter().zip(expected).enumerate() {
            assert!(
                (actual - expected).abs() <= tolerance,
                "index {index}: expected {expected:.12}, got {actual:.12}"
            );
        }
    }

    fn assert_same_bits(actual: &[f64], expected: &[f64]) {
        assert_eq!(actual.len(), expected.len());
        for (index, (&actual, &expected)) in actual.iter().zip(expected).enumerate() {
            assert_eq!(
                actual.to_bits(),
                expected.to_bits(),
                "index {index}: expected bits {:016x}, got {:016x}",
                expected.to_bits(),
                actual.to_bits()
            );
        }
    }

    fn gradcheck(mut probe: Tensor, analytic: &Tensor, objective: impl FnMut(&Tensor) -> f64) {
        let samples = probe.len();
        let report = sampled_tensor_gradient_check(
            &mut probe,
            &analytic.view(),
            STEP,
            TOLERANCE,
            samples,
            objective,
        )
        .unwrap();
        assert!(report.checks.iter().all(|check| check.comparison.passed));
    }

    #[test]
    fn repeated_lookup_pipeline_has_exact_signs_and_accumulation() {
        let embeddings = parameter(&[3, 2], &[2.0, 2.0, 1.0, -1.0, -1.0, 1.0]);
        let weights = parameter(&[2, 2], &[1.0, -1.0, 1.0, -1.0]);
        let gathered = embeddings.gather_rows(&[1, 1, 1, 2], &[4]).unwrap();
        let logits = gathered.matmul(&weights).unwrap().silu().unwrap();
        let loss = logits.indexed_mean_nll(1, &[0, 0, 0, 1]).unwrap();

        assert_close(loss.value().as_slice(), &[2.0_f64.ln()], 1e-12);
        let pass = loss.backward_with_trace().unwrap();
        assert_eq!(
            pass.nodes.last().unwrap().operation,
            TensorOperation::IndexedMeanNll
        );
        assert_close(
            embeddings.gradient().unwrap().as_slice(),
            &[0.0, 0.0, -0.375, -0.375, 0.125, 0.125],
            1e-12,
        );
        assert_close(
            weights.gradient().unwrap().as_slice(),
            &[-0.25, 0.25, 0.25, -0.25],
            1e-12,
        );
    }

