            .unwrap()
            .backward()
            .unwrap();
        gradcheck(
            tensor(&[2, 3], &logits_values),
            &nll_logits.gradient().unwrap(),
            |probe| indexed_mean_nll(&probe.view(), 1, &[2, 0]).unwrap(),
        );
    }

    #[test]
    fn batched_matmul_unbroadcasts_both_parent_gradients() {
        let left = parameter(&[2, 2], &[1.0, 2.0, 3.0, 4.0]);
        let right = parameter(
            &[3, 2, 2],
