        let right_single = parameter(&[2, 2], &[1.0, 2.0, 3.0, 4.0]);
        sum_to_scalar(left_batched.matmul(&right_single).unwrap())
            .backward()
            .unwrap();
        assert_eq!(left_batched.gradient().unwrap().shape(), &[3, 2, 2]);
        assert_eq!(
