                "en-river-dawn",
                "ru-river-dawn",
                "en-clock-shop",
                "ru-clock-shop",
                "en-rain-library",
                "ru-rain-library",
                "en-bee-garden",
                "ru-bee-garden",
            ]
        );
        assert_eq!(
            partitions.document_ids(Partition::Validation),
            ["en-night-station", "ru-night-station"]
