            ),
            Err(EvaluationError::WrongSelectionPartition {
                actual: Partition::Train
            })
        ));
        for invalid_loss in [f64::NAN, -0.25, f64::INFINITY, f64::NEG_INFINITY] {
            assert!(matches!(
                SelectedDecoder::new(
                    &state,
