        {
            let mut session = cache.bind(&model).unwrap();
            session.prefill(&[0, 1]).unwrap();
            session.reset();
        }
        let before = cache.clone();
        let mut optimizer = AdamW::new(AdamWConfig::new(0.01, 0.9, 0.999, 1e-8, 0.1).unwrap());

        optimizer.step(model.parameters()).unwrap();

        assert!(matches!(
