    #[test]
    fn forward_validation_precedence_is_shape_count_then_first_bad_id() {
        let embedding = known_embedding();
        assert_eq!(
            embedding
                .forward(&[u32::MAX], &[usize::MAX, 2])
                .unwrap_err(),
            EmbeddingError::TokenShape(TensorError::ShapeOverflow)
        );
        assert_eq!(
            embedding.forward(&[u32::MAX], &[2]).unwrap_err(),
            EmbeddingError::TokenCountMismatch {
                expected: 2,
                actual: 1,
            }
        );
        assert_eq!(
            embedding.forward(&[1, u32::MAX, 4], &[3]).unwrap_err(),
            EmbeddingError::TokenIdOutOfBounds {
                position: 1,
                id: u32::MAX,
                vocabulary_size: 4,
            }
        );
        assert_eq!(
            embedding
                .forward(&[u32::MAX], &[0, usize::MAX])
                .unwrap_err(),
            EmbeddingError::TokenCountMismatch {
                expected: 0,
                actual: 1,
            }
        );
        assert_eq!(
            embedding.forward(&[], &[0, usize::MAX]).unwrap_err(),
            EmbeddingError::Autodiff(TensorAutodiffError::Tensor(TensorError::ShapeOverflow))
        );
    }

    #[test]
    fn manual_table_validation_is_rank_then_vocabulary_then_width() {
        let make = |shape: &[usize], values: &[f64]| {
            NamedParameter::from_tensor("token_embedding.weight", tensor(shape, values)).unwrap()
        };
        assert_eq!(
            Embedding::from_parameter(make(&[2], &[1.0, 2.0])).unwrap_err(),
            EmbeddingError::TableRank { rank: 1 }
        );
        assert_eq!(
            Embedding::from_parameter(make(&[1, 1, 1], &[1.0])).unwrap_err(),
            EmbeddingError::TableRank { rank: 3 }
        );
        assert_eq!(
            Embedding::from_parameter(make(&[0, 2], &[])).unwrap_err(),
            EmbeddingError::EmptyVocabulary
        );
        assert_eq!(
            Embedding::from_parameter(make(&[2, 0], &[])).unwrap_err(),
            EmbeddingError::ZeroEmbeddingWidth
        );
        assert_eq!(
            Embedding::from_parameter(make(&[0, 0], &[])).unwrap_err(),
            EmbeddingError::EmptyVocabulary
        );
    }

    #[test]
    fn construction_is_transactional_reproducible_and_preserves_identity() {
        let mut rejected_rng = SplitMix64::from_seed(18);
        let rejected_state = rejected_rng.state();
        assert_eq!(
            Embedding::new("Bad", 0, 0, &mut rejected_rng).unwrap_err(),
            EmbeddingError::Initialization(InitializationError::InvalidNameCharacter {
                index: 0,
                byte: b'B',
            })
        );
        assert_eq!(rejected_rng.state(), rejected_state);
        assert_eq!(
            Embedding::new("token_embedding.weight", 0, 0, &mut rejected_rng).unwrap_err(),
            EmbeddingError::EmptyVocabulary
        );
        assert_eq!(
            Embedding::new("token_embedding.weight", 4, 0, &mut rejected_rng).unwrap_err(),
            EmbeddingError::ZeroEmbeddingWidth
        );
        assert_eq!(rejected_rng.state(), rejected_state);

        let mut left_rng = SplitMix64::from_seed(18);
        let mut right_rng = SplitMix64::from_seed(18);
        let left = Embedding::new("token_embedding.weight", 4, 2, &mut left_rng).unwrap();
        let right = Embedding::new("token_embedding.weight", 4, 2, &mut right_rng).unwrap();
        assert_eq!(left.table().name(), "token_embedding.weight");
        assert_eq!(left.table().tensor().shape(), vec![4, 2]);
        assert_eq!(
            &*left.table().tensor().value(),
            &*right.table().tensor().value()
        );
        assert!(!left.table().tensor().is_same_node(right.table().tensor()));

        let clone = left.clone();
        assert!(left.table().tensor().is_same_node(clone.table().tensor()));
        assert!(
            left.parameters()[0]
                .tensor()
                .is_same_node(left.table().tensor())
        );
        let output = left.forward(&[1], &[1]).unwrap();
        output
            .backward_with_seed(&tensor(&[1, 2], &[1.0, 1.0]).view(), GraphRetention::Retain)
            .unwrap();
        assert_eq!(
            left.table().tensor().gradient().unwrap().as_slice()[2..4],
            [1.0, 1.0]
        );
        assert_eq!(left.vocabulary_size(), 4);
        assert_eq!(left.embedding_width(), 2);
    }
}

//! Deterministic, width-aware construction of named trainable parameters.

use std::error::Error;
use std::fmt;

use crate::autograd::tensor_core::{TensorAutodiffError, TensorValue};
use crate::tensor::storage::{Tensor, TensorError};

const SPLITMIX_INCREMENT: u64 = 0x9e37_79b9_7f4a_7c15;
const SPLITMIX_MIX_ONE: u64 = 0xbf58_476d_1ce4_e5b9;
const SPLITMIX_MIX_TWO: u64 = 0x94d0_49bb_1331_11eb;
const BINARY64_UNIT_SCALE: f64 = 1.0 / ((1_u64 << 53) as f64);

// region:parameter-init-errors
/// A deterministic rejection while constructing or collecting a parameter.
#[derive(Clone, Debug, PartialEq)]
pub enum InitializationError {
    EmptyName,
    EmptyNameSegment {
        index: usize,
    },
    InvalidNameCharacter {
        index: usize,
        byte: u8,
    },
    ZeroFanIn,
    ZeroFanOut,
    FanSumOverflow {
        fan_in: usize,
        fan_out: usize,
    },
    ShapeProductOverflow {
        fan_in: usize,
        fan_out: usize,
    },
    AllocationFailed {
        elements: usize,
    },
    DuplicateName {
        name: String,
        first: usize,
        repeated: usize,
    },
    Tensor(TensorError),
    Autodiff(TensorAutodiffError),
}

impl fmt::Display for InitializationError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::EmptyName => formatter.write_str("parameter name must not be empty"),
            Self::EmptyNameSegment { index } => write!(
                formatter,
                "parameter name has an empty dot-separated segment at byte {index}"
            ),
            Self::InvalidNameCharacter { index, byte } => write!(
                formatter,
                "parameter name byte {index} must be lowercase ASCII, a digit, underscore, or dot; got 0x{byte:02x}"
            ),
            Self::ZeroFanIn => formatter.write_str("fan-in must be greater than zero"),
            Self::ZeroFanOut => formatter.write_str("fan-out must be greater than zero"),
            Self::FanSumOverflow { fan_in, fan_out } => write!(
                formatter,
                "fan-in {fan_in} plus fan-out {fan_out} does not fit usize"
            ),
            Self::ShapeProductOverflow { fan_in, fan_out } => write!(
                formatter,
                "matrix shape [{fan_in},{fan_out}] does not fit usize"
            ),
            Self::AllocationFailed { elements } => write!(
                formatter,
                "could not reserve storage for {elements} initialized values"
            ),
            Self::DuplicateName {
                name,
                first,
                repeated,
            } => write!(
                formatter,
                "parameter name {name:?} first appears at index {first} and repeats at index {repeated}"
            ),
            Self::Tensor(error) => error.fmt(formatter),
            Self::Autodiff(error) => error.fmt(formatter),
        }
    }
}

impl Error for InitializationError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            Self::Tensor(error) => Some(error),
            Self::Autodiff(error) => Some(error),
            _ => None,
        }
    }
}

impl From<TensorError> for InitializationError {
    fn from(error: TensorError) -> Self {
        Self::Tensor(error)
    }
}

impl From<TensorAutodiffError> for InitializationError {
    fn from(error: TensorAutodiffError) -> Self {
        Self::Autodiff(error)
    }
}
// endregion:parameter-init-errors

// region:deterministic-prng
/// A small deterministic generator with an explicit resumable 64-bit state.
///
/// This generator is suitable for reproducible teaching fixtures. It is not a
/// cryptographically secure random-number generator.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct SplitMix64 {
    state: u64,
}

impl SplitMix64 {
    /// Treats `seed` as the raw state before the first increment and draw.
    pub const fn from_seed(seed: u64) -> Self {
        Self { state: seed }
    }

    /// Resumes directly from a previously recorded raw state.
    pub const fn from_state(state: u64) -> Self {
        Self { state }
    }

    /// Returns the raw state that the next draw will advance.
    pub const fn state(&self) -> u64 {
        self.state
    }

    /// Advances and mixes one exactly specified 64-bit value.
    pub fn next_u64(&mut self) -> u64 {
        self.state = self.state.wrapping_add(SPLITMIX_INCREMENT);
        let mut value = self.state;
        value = (value ^ (value >> 30)).wrapping_mul(SPLITMIX_MIX_ONE);
        value = (value ^ (value >> 27)).wrapping_mul(SPLITMIX_MIX_TWO);
        value ^ (value >> 31)
    }

    /// Maps the high 53 bits of one draw to the binary64 interval [0,1).
    pub fn next_unit_f64(&mut self) -> f64 {
        ((self.next_u64() >> 11) as f64) * BINARY64_UNIT_SCALE
    }
}
// endregion:deterministic-prng

// region:xavier-initialization
/// The formula-derived scale for one [fan-in, fan-out] matrix.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct XavierScale {
    fan_in: usize,
    fan_out: usize,
    target_variance: f64,
    standard_deviation: f64,
    uniform_limit: f64,
}

impl XavierScale {
    pub const fn fan_in(self) -> usize {
        self.fan_in
    }

    pub const fn fan_out(self) -> usize {
        self.fan_out
    }

    pub const fn target_variance(self) -> f64 {
        self.target_variance
    }

    pub const fn standard_deviation(self) -> f64 {
        self.standard_deviation
    }

    pub const fn uniform_limit(self) -> f64 {
        self.uniform_limit
    }
}

/// Calculates the Xavier variance, standard deviation, and uniform bound.
pub fn xavier_scale(fan_in: usize, fan_out: usize) -> Result<XavierScale, InitializationError> {
    if fan_in == 0 {
        return Err(InitializationError::ZeroFanIn);
    }
    if fan_out == 0 {
        return Err(InitializationError::ZeroFanOut);
    }
    let fan_sum = fan_in
        .checked_add(fan_out)
        .ok_or(InitializationError::FanSumOverflow { fan_in, fan_out })?;
    let target_variance = 2.0 / fan_sum as f64;
    Ok(XavierScale {
        fan_in,
        fan_out,
        target_variance,
        standard_deviation: target_variance.sqrt(),
        uniform_limit: (6.0 / fan_sum as f64).sqrt(),
    })
}

fn checked_element_count(fan_in: usize, fan_out: usize) -> Result<usize, InitializationError> {
    fan_in
        .checked_mul(fan_out)
        .ok_or(InitializationError::ShapeProductOverflow { fan_in, fan_out })
}

pub(crate) fn validate_name(name: &str) -> Result<(), InitializationError> {
    if name.is_empty() {
        return Err(InitializationError::EmptyName);
    }

    let mut previous_was_dot = true;
    for (index, byte) in name.bytes().enumerate() {
        if byte == b'.' {
            if previous_was_dot {
                return Err(InitializationError::EmptyNameSegment { index });
            }
            previous_was_dot = true;
            continue;
        }

        if !(byte.is_ascii_lowercase() || byte.is_ascii_digit() || byte == b'_') {
            return Err(InitializationError::InvalidNameCharacter { index, byte });
        }
        previous_was_dot = false;
    }

    if previous_was_dot {
        return Err(InitializationError::EmptyNameSegment { index: name.len() });
    }
    Ok(())
}

fn initialized_values(
    rng: &mut SplitMix64,
    scale: XavierScale,
) -> Result<Vec<f64>, InitializationError> {
    let elements = checked_element_count(scale.fan_in, scale.fan_out)?;
    let mut values = Vec::new();
    values
        .try_reserve_exact(elements)
        .map_err(|_| InitializationError::AllocationFailed { elements })?;
    for _ in 0..elements {
        let centered = 2.0 * rng.next_unit_f64() - 1.0;
        values.push(scale.uniform_limit * centered);
    }
    Ok(values)
}
// endregion:xavier-initialization

// region:named-parameters
/// One immutable external name paired with one trainable tensor-tape leaf.
#[derive(Clone, Debug)]
pub struct NamedParameter {
    name: String,
    tensor: TensorValue,
}

impl NamedParameter {
    /// Wraps an already-created tensor as a named trainable leaf.
    pub fn from_tensor(
        name: impl Into<String>,
        tensor: Tensor,
    ) -> Result<Self, InitializationError> {
        let name = name.into();
        validate_name(&name)?;
        Ok(Self {
            name,
            tensor: TensorValue::parameter(tensor)?,
        })
    }

    /// Samples one [fan-in, fan-out] trainable matrix transactionally.
    pub fn xavier_uniform(
        name: impl Into<String>,
        fan_in: usize,
        fan_out: usize,
        rng: &mut SplitMix64,
    ) -> Result<Self, InitializationError> {
        let name = name.into();
        validate_name(&name)?;
        let scale = xavier_scale(fan_in, fan_out)?;
        let elements = checked_element_count(fan_in, fan_out)?;

        let mut trial = rng.clone();
        let values = initialized_values(&mut trial, scale)?;
        debug_assert_eq!(values.len(), elements);
        let tensor = Tensor::from_vec(vec![fan_in, fan_out], values)?;
        let parameter = Self {
            name,
            tensor: TensorValue::parameter(tensor)?,
        };
        *rng = trial;
        Ok(parameter)
    }

    /// Returns the stable external identity used by layers and checkpoints.
    pub fn name(&self) -> &str {
        &self.name
    }

    /// Borrows the trainable tape leaf without duplicating its tensor storage.
    pub fn tensor(&self) -> &TensorValue {
        &self.tensor
    }
}

/// A duplicate-checked, declaration-ordered set of named parameters.
#[derive(Clone, Debug, Default)]
pub struct NamedParameters {
    parameters: Vec<NamedParameter>,
}

impl NamedParameters {
    pub fn try_new(parameters: Vec<NamedParameter>) -> Result<Self, InitializationError> {
        for repeated in 0..parameters.len() {
            if let Some(first) = parameters[..repeated]
                .iter()
                .position(|parameter| parameter.name() == parameters[repeated].name())
            {
                return Err(InitializationError::DuplicateName {
                    name: parameters[repeated].name().to_owned(),
                    first,
                    repeated,
                });
            }
        }
        Ok(Self { parameters })
    }

    pub fn len(&self) -> usize {
        self.parameters.len()
    }

    pub fn is_empty(&self) -> bool {
        self.parameters.is_empty()
    }

    pub fn as_slice(&self) -> &[NamedParameter] {
        &self.parameters
    }

    pub fn iter(&self) -> impl ExactSizeIterator<Item = &NamedParameter> {
        self.parameters.iter()
    }

    pub fn get(&self, name: &str) -> Option<&NamedParameter> {
        self.parameters
            .iter()
            .find(|parameter| parameter.name() == name)
    }
}
// endregion:named-parameters

impl NamedParameter {
    /// Validates a borrowed name and tensor without creating a node or copying values.
    pub(crate) fn validate_leaf(name: &str, tensor: &Tensor) -> Result<(), InitializationError> {
        validate_name(name)?;
        TensorValue::validate_parameter_value(tensor)?;
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::autograd::tensor_core::{TensorAutodiffError, TensorOperation};

    fn finite_tensor(shape: &[usize], values: &[f64]) -> Tensor {
        Tensor::from_vec(shape.to_vec(), values.to_vec()).unwrap()
    }

    #[test]
    fn splitmix64_matches_the_seed_zero_reference_sequence() {
        let mut rng = SplitMix64::from_seed(0);
        assert_eq!(
            [
                rng.next_u64(),
                rng.next_u64(),
                rng.next_u64(),
                rng.next_u64(),
            ],
            [
                0xe220_a839_7b1d_cdaf,
                0x6e78_9e6a_a1b9_65f4,
                0x06c4_5d18_8009_454f,
                0xf88b_b8a8_724c_81ec,
            ]
        );
    }

    #[test]
    fn cloned_and_resumed_generators_preserve_the_exact_state() {
        let mut rng = SplitMix64::from_seed(17);
        let first = rng.next_u64();
        let state = rng.state();
        let mut cloned = rng.clone();
        let mut resumed = SplitMix64::from_state(state);

        let cloned_next = cloned.next_u64();
        let resumed_next = resumed.next_u64();
        assert_ne!(first, cloned_next);
        assert_eq!(cloned_next, resumed_next);
        assert_eq!(cloned.state(), resumed.state());
        assert_eq!(cloned.next_u64(), resumed.next_u64());
    }

    #[test]
    fn unit_values_stay_in_the_half_open_interval() {
        let mut rng = SplitMix64::from_seed(0);
        for _ in 0..10_000 {
            let value = rng.next_unit_f64();
            assert!((0.0..1.0).contains(&value));
        }
    }

    #[test]
    fn xavier_scale_matches_the_formula() {
        let square = xavier_scale(2, 2).unwrap();
        assert_eq!(square.target_variance(), 0.5);
        assert_eq!(square.standard_deviation(), (0.5_f64).sqrt());
        assert_eq!(square.uniform_limit(), (1.5_f64).sqrt());

        let doubled_input = xavier_scale(4, 2).unwrap();
        assert_eq!(doubled_input.target_variance(), 1.0 / 3.0);
        assert_eq!(doubled_input.standard_deviation(), (1.0_f64 / 3.0).sqrt());
        assert_eq!(doubled_input.uniform_limit(), 1.0);
    }

    #[test]
    fn frozen_seed_seventeen_parameter_matches_exact_binary64_values() {
        let mut rng = SplitMix64::from_seed(17);
        let parameter =
            NamedParameter::xavier_uniform("projection.weight", 2, 2, &mut rng).unwrap();
        let bits: Vec<_> = parameter
            .tensor()
            .value()
            .as_slice()
            .iter()
            .map(|value| value.to_bits())
            .collect();

        assert_eq!(
            bits,
            [
                0x3f74_4760_bbbf_c4e2,
                0xbfd1_0508_0689_42ad,
                0xbfda_e98b_1d44_f6ae,
                0xbfe5_a45c_1710_f8d8,
            ]
        );
    }

    #[test]
    fn same_stream_reproduces_and_one_shared_stream_separates_parameters() {
        let mut left_rng = SplitMix64::from_seed(17);
        let mut right_rng = SplitMix64::from_seed(17);
        let left = NamedParameter::xavier_uniform("projection.left", 2, 2, &mut left_rng).unwrap();
        let right =
            NamedParameter::xavier_uniform("projection.right", 2, 2, &mut right_rng).unwrap();
        assert_eq!(&*left.tensor().value(), &*right.tensor().value());

        let second =
            NamedParameter::xavier_uniform("projection.second", 2, 2, &mut left_rng).unwrap();
        assert_ne!(&*left.tensor().value(), &*second.tensor().value());
    }

    #[test]
    fn selected_distinct_seed_changes_the_frozen_parameter() {
        let mut first_rng = SplitMix64::from_seed(17);
        let mut second_rng = SplitMix64::from_seed(18);
        let first =
            NamedParameter::xavier_uniform("projection.weight", 2, 2, &mut first_rng).unwrap();
        let second =
            NamedParameter::xavier_uniform("projection.weight", 2, 2, &mut second_rng).unwrap();
        assert_ne!(&*first.tensor().value(), &*second.tensor().value());
    }

    #[test]
    fn xavier_values_are_finite_row_major_and_inside_the_bound() {
        let mut rng = SplitMix64::from_seed(9);
        let parameter = NamedParameter::xavier_uniform("wide.weight", 3, 5, &mut rng).unwrap();
        let value = parameter.tensor().value();
        let limit = xavier_scale(3, 5).unwrap().uniform_limit();

        assert_eq!(value.shape(), &[3, 5]);
        assert_eq!(value.len(), 15);
        assert!(
            value
                .as_slice()
                .iter()
                .all(|entry| entry.is_finite() && *entry >= -limit && *entry < limit)
        );
        assert_eq!(
            rng.state(),
            9_u64.wrapping_add(SPLITMIX_INCREMENT.wrapping_mul(15))
        );
    }

    #[test]
    fn validation_precedence_and_failures_preserve_rng_state() {
        let mut rng = SplitMix64::from_seed(23);
        let state = rng.state();

        assert_eq!(
            NamedParameter::xavier_uniform("", 0, 0, &mut rng).unwrap_err(),
            InitializationError::EmptyName
        );
        assert_eq!(
            NamedParameter::xavier_uniform(".bad", 0, 0, &mut rng).unwrap_err(),
            InitializationError::EmptyNameSegment { index: 0 }
        );
        assert_eq!(
            NamedParameter::xavier_uniform("Bad", 0, 0, &mut rng).unwrap_err(),
            InitializationError::InvalidNameCharacter {
                index: 0,
                byte: b'B',
            }
        );
        assert_eq!(
            NamedParameter::xavier_uniform("valid.weight", 0, 0, &mut rng).unwrap_err(),
            InitializationError::ZeroFanIn
        );
        assert_eq!(
            NamedParameter::xavier_uniform("valid.weight", 1, 0, &mut rng).unwrap_err(),
            InitializationError::ZeroFanOut
        );
        assert_eq!(
            NamedParameter::xavier_uniform("valid.weight", usize::MAX, 1, &mut rng).unwrap_err(),
            InitializationError::FanSumOverflow {
                fan_in: usize::MAX,
                fan_out: 1,
            }
        );
        let product_fan_in = usize::MAX / 2 + 1;
        assert_eq!(
            NamedParameter::xavier_uniform("valid.weight", product_fan_in, 2, &mut rng)
                .unwrap_err(),
            InitializationError::ShapeProductOverflow {
                fan_in: product_fan_in,
                fan_out: 2,
            }
        );
        assert_eq!(rng.state(), state);
    }

    #[test]
    fn parameter_name_grammar_accepts_declared_segments_and_rejects_every_gap() {
        assert!(validate_name("block_0.attention2.query_weight").is_ok());
        assert_eq!(
            validate_name("valid..weight").unwrap_err(),
            InitializationError::EmptyNameSegment { index: 6 }
        );
        assert_eq!(
            validate_name("valid.").unwrap_err(),
            InitializationError::EmptyNameSegment { index: 6 }
        );
        assert_eq!(
            validate_name("bad-name").unwrap_err(),
            InitializationError::InvalidNameCharacter {
                index: 3,
                byte: b'-',
            }
        );
        assert_eq!(
            validate_name("naïve").unwrap_err(),
            InitializationError::InvalidNameCharacter {
                index: 2,
                byte: 0xc3,
            }
        );
    }

    #[test]
    fn deterministic_capacity_failure_preserves_rng_state() {
        let mut rng = SplitMix64::from_seed(31);
        let state = rng.state();
        let too_many_f64s = (isize::MAX as usize) / std::mem::size_of::<f64>() + 1;

        assert_eq!(
            NamedParameter::xavier_uniform("huge.weight", too_many_f64s, 1, &mut rng).unwrap_err(),
            InitializationError::AllocationFailed {
                elements: too_many_f64s,
            }
        );
        assert_eq!(rng.state(), state);
    }

    #[test]
    fn manual_parameters_validate_names_before_tensor_values() {
        let nonfinite = finite_tensor(&[1], &[f64::NAN]);
        assert_eq!(
            NamedParameter::from_tensor("Bad", nonfinite.clone()).unwrap_err(),
            InitializationError::InvalidNameCharacter {
                index: 0,
                byte: b'B',
            }
        );
        let error = NamedParameter::from_tensor("manual.weight", nonfinite).unwrap_err();
        assert!(error.source().is_some());
        match error {
            InitializationError::Autodiff(TensorAutodiffError::NonFiniteLeaf {
                operation: TensorOperation::Parameter,
                index: 0,
                value,
            }) => assert!(value.is_nan()),
            other => panic!("unexpected error: {other:?}"),
        }
    }

    #[test]
    fn clone_preserves_leaf_identity_but_equal_recreation_does_not() {
        let tensor = finite_tensor(&[2], &[1.0, -1.0]);
        let parameter = NamedParameter::from_tensor("shared.weight", tensor.clone()).unwrap();
        let clone = parameter.clone();
        let recreated = NamedParameter::from_tensor("shared.weight", tensor).unwrap();

        assert!(parameter.tensor().is_same_node(clone.tensor()));
        assert!(!parameter.tensor().is_same_node(recreated.tensor()));
        assert_eq!(&*parameter.tensor().value(), &*recreated.tensor().value());
        let gradient = parameter.tensor().gradient().unwrap();
        assert!(gradient.as_slice().iter().all(|value| value.to_bits() == 0));
    }

    #[test]
    fn named_collection_preserves_order_lookup_and_empty_state() {
        let empty = NamedParameters::try_new(Vec::new()).unwrap();
        assert!(empty.is_empty());
        assert_eq!(empty.len(), 0);

        let first = NamedParameter::from_tensor(
            "embedding.weight",
            finite_tensor(&[2, 2], &[1.0, 2.0, 3.0, 4.0]),
        )
        .unwrap();
        let second =
            NamedParameter::from_tensor("projection.weight", finite_tensor(&[2, 1], &[5.0, 6.0]))
                .unwrap();
        let parameters = NamedParameters::try_new(vec![first.clone(), second.clone()]).unwrap();

        assert_eq!(
            parameters
                .iter()
                .map(NamedParameter::name)
                .collect::<Vec<_>>(),
            ["embedding.weight", "projection.weight"]
        );
        assert!(
            parameters
                .get("embedding.weight")
                .unwrap()
                .tensor()
                .is_same_node(first.tensor())
        );
        assert!(parameters.get("missing").is_none());
        assert_eq!(parameters.as_slice().len(), 2);
    }

    #[test]
    fn named_collection_reports_the_first_duplicate_pair() {
        let make = |name| NamedParameter::from_tensor(name, finite_tensor(&[1], &[1.0])).unwrap();
        assert_eq!(
            NamedParameters::try_new(vec![
                make("a.weight"),
                make("b.weight"),
                make("a.weight"),
                make("b.weight"),
            ])
            .unwrap_err(),
            InitializationError::DuplicateName {
                name: "a.weight".to_owned(),
                first: 0,
                repeated: 2,
            }
        );
    }
}

//! A named trainable projection over the final feature axis.

use std::error::Error;
use std::fmt;

use crate::autograd::tensor_core::{AutogradContext, TensorAutodiffError, TensorValue};
use crate::nn::init::{InitializationError, NamedParameter, NamedParameters, SplitMix64};
use crate::tensor::storage::Tensor;

// region:linear-errors
/// A rejected parameter set, input shape, allocation, or delegated tape operation.
#[derive(Clone, Debug, PartialEq)]
pub enum LinearError {
    Initialization(InitializationError),
    Autodiff(TensorAutodiffError),
    WeightRank { rank: usize },
    ZeroInputWidth,
    ZeroOutputWidth,
    BiasRank { rank: usize },
    BiasWidthMismatch { expected: usize, actual: usize },
    InputRank { rank: usize },
    InputWidthMismatch { expected: usize, actual: usize },
    BiasAllocationFailed { elements: usize },
}

impl fmt::Display for LinearError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Initialization(error) => error.fmt(formatter),
            Self::Autodiff(error) => error.fmt(formatter),
            Self::WeightRank { rank } => {
                write!(
                    formatter,
                    "linear weight must have rank two, got rank {rank}"
                )
            }
            Self::ZeroInputWidth => {
                formatter.write_str("linear input width must be greater than zero")
            }
            Self::ZeroOutputWidth => {
                formatter.write_str("linear output width must be greater than zero")
            }
            Self::BiasRank { rank } => {
                write!(formatter, "linear bias must have rank one, got rank {rank}")
            }
            Self::BiasWidthMismatch { expected, actual } => write!(
                formatter,
                "linear bias width must equal output width {expected}, got {actual}"
            ),
            Self::InputRank { rank } => write!(
                formatter,
                "linear input must have at least one feature axis, got rank {rank}"
            ),
            Self::InputWidthMismatch { expected, actual } => write!(
                formatter,
                "linear input final width must equal {expected}, got {actual}"
            ),
            Self::BiasAllocationFailed { elements } => write!(
                formatter,
                "could not reserve storage for {elements} linear bias values"
            ),
        }
    }
}

impl Error for LinearError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            Self::Initialization(error) => Some(error),
            Self::Autodiff(error) => Some(error),
            _ => None,
        }
    }
}

impl From<InitializationError> for LinearError {
    fn from(error: InitializationError) -> Self {
        Self::Initialization(error)
    }
}

impl From<TensorAutodiffError> for LinearError {
    fn from(error: TensorAutodiffError) -> Self {
        Self::Autodiff(error)
    }
}
// endregion:linear-errors

// region:linear-layer
/// One `[input_width, output_width]` feature projection with optional bias.
#[derive(Clone, Debug)]
pub struct Linear {
    parameters: NamedParameters,
    input_width: usize,
    output_width: usize,
    has_bias: bool,
}

impl Linear {
    /// Initializes a named weight and optional zero bias without partially advancing `rng`.
    pub fn new(
        parameter_prefix: impl Into<String>,
        input_width: usize,
        output_width: usize,
        with_bias: bool,
        rng: &mut SplitMix64,
    ) -> Result<Self, LinearError> {
        let parameter_prefix = parameter_prefix.into();
        let mut trial = rng.clone();
        let weight = NamedParameter::xavier_uniform(
            format!("{parameter_prefix}.weight"),
            input_width,
            output_width,
            &mut trial,
        )
        .map_err(|error| match error {
            InitializationError::ZeroFanIn => LinearError::ZeroInputWidth,
            InitializationError::ZeroFanOut => LinearError::ZeroOutputWidth,
            other => LinearError::Initialization(other),
        })?;

        let bias = if with_bias {
            let mut values = Vec::new();
            values.try_reserve_exact(output_width).map_err(|_| {
                LinearError::BiasAllocationFailed {
                    elements: output_width,
                }
            })?;
            values.resize(output_width, 0.0);
            let tensor = Tensor::from_vec(vec![output_width], values)
                .map_err(InitializationError::Tensor)?;
            Some(NamedParameter::from_tensor(
                format!("{parameter_prefix}.bias"),
                tensor,
            )?)
        } else {
            None
        };

        let layer = Self::from_parameters(weight, bias)?;
        *rng = trial;
        Ok(layer)
    }

    /// Gives layer semantics to an existing weight and optional bias.
    pub fn from_parameters(
        weight: NamedParameter,
        bias: Option<NamedParameter>,
    ) -> Result<Self, LinearError> {
        let weight_shape = weight.tensor().shape();
        if weight_shape.len() != 2 {
            return Err(LinearError::WeightRank {
                rank: weight_shape.len(),
            });
        }
        let input_width = weight_shape[0];
        let output_width = weight_shape[1];
        if input_width == 0 {
            return Err(LinearError::ZeroInputWidth);
        }
        if output_width == 0 {
            return Err(LinearError::ZeroOutputWidth);
        }

        if let Some(parameter) = &bias {
            let bias_shape = parameter.tensor().shape();
            if bias_shape.len() != 1 {
                return Err(LinearError::BiasRank {
                    rank: bias_shape.len(),
                });
            }
            if bias_shape[0] != output_width {
                return Err(LinearError::BiasWidthMismatch {
                    expected: output_width,
                    actual: bias_shape[0],
                });
            }
        }

        let has_bias = bias.is_some();
        let mut parameters = vec![weight];
        if let Some(bias) = bias {
            parameters.push(bias);
        }
        Ok(Self {
            parameters: NamedParameters::try_new(parameters)?,
            input_width,
            output_width,
            has_bias,
        })
    }

    /// Projects only the final feature axis and preserves every leading axis.
    pub fn forward(&self, input: &TensorValue) -> Result<TensorValue, LinearError> {
        self.forward_with_context(AutogradContext::recording(), input)
    }

    /// Projects the final feature axis under an explicit recording policy.
    pub fn forward_with_context(
        &self,
        context: AutogradContext,
        input: &TensorValue,
    ) -> Result<TensorValue, LinearError> {
        let input_shape = input.shape();
        if input_shape.is_empty() {
            return Err(LinearError::InputRank { rank: 0 });
        }
        let actual_width = *input_shape.last().expect("nonempty input shape");
        if actual_width != self.input_width {
            return Err(LinearError::InputWidthMismatch {
                expected: self.input_width,
                actual: actual_width,
            });
        }

        let projected = if input_shape.len() == 1 {
            let promoted = input.reshape_with_context(context, &[1, self.input_width])?;
            let output = promoted.matmul_with_context(context, self.weight().tensor())?;
            let output = match self.bias() {
                Some(bias) => output.add_with_context(context, bias.tensor())?,
                None => output,
            };
            output.reshape_with_context(context, &[self.output_width])?
        } else {
            let output = input.matmul_with_context(context, self.weight().tensor())?;
            match self.bias() {
                Some(bias) => output.add_with_context(context, bias.tensor())?,
                None => output,
            }
        };
        Ok(projected)
    }

    pub fn weight(&self) -> &NamedParameter {
        &self.parameters.as_slice()[0]
    }

    pub fn bias(&self) -> Option<&NamedParameter> {
        self.has_bias.then(|| &self.parameters.as_slice()[1])
    }

    pub fn parameters(&self) -> &[NamedParameter] {
        self.parameters.as_slice()
    }

    pub const fn input_width(&self) -> usize {
        self.input_width
    }

    pub const fn output_width(&self) -> usize {
        self.output_width
    }

    pub const fn has_bias(&self) -> bool {
        self.has_bias
    }

    pub const fn parameter_count(&self) -> usize {
        let weight_count = self.input_width * self.output_width;
        if self.has_bias {
            weight_count + self.output_width
        } else {
            weight_count
        }
    }
}
// endregion:linear-layer

#[cfg(test)]
mod tests {
    use super::*;
    use crate::autograd::gradcheck::sampled_tensor_gradient_check;
    use crate::autograd::tensor_core::GraphRetention;

    const STEP: f64 = 1e-6;
    const TOLERANCE: f64 = 2e-6;

    fn tensor(shape: &[usize], values: &[f64]) -> Tensor {
        Tensor::from_vec(shape.to_vec(), values.to_vec()).unwrap()
    }

    fn parameter(name: &str, shape: &[usize], values: &[f64]) -> NamedParameter {
        NamedParameter::from_tensor(name, tensor(shape, values)).unwrap()
    }

    fn known_layer(with_bias: bool) -> Linear {
        Linear::from_parameters(
            parameter(
                "token_projection.weight",
                &[2, 3],
                &[1.0, 0.0, -1.0, 2.0, 0.5, 1.0],
            ),
            with_bias.then(|| parameter("token_projection.bias", &[3], &[0.5, -0.5, 1.0])),
        )
        .unwrap()
    }

    fn sum_values(value: &TensorValue) -> f64 {
        value.value().as_slice().iter().sum()
    }

    #[test]
    fn known_affine_forward_and_nonuniform_reverse_seed_are_exact() {
        let layer = known_layer(true);
        let input = TensorValue::parameter(tensor(&[1, 2, 2], &[1.0, 2.0, -1.0, 3.0])).unwrap();
        let output = layer.forward(&input).unwrap();
        assert_eq!(output.shape(), [1, 2, 3]);
        assert_eq!(output.value().as_slice(), &[5.5, 0.5, 2.0, 5.5, 1.0, 5.0]);

        let upstream = tensor(&[1, 2, 3], &[1.0, 0.0, -1.0, 0.5, 2.0, 1.0]);
        output
            .backward_with_seed(&upstream.view(), GraphRetention::Retain)
            .unwrap();
        assert_eq!(input.gradient().unwrap().as_slice(), &[2.0, 1.0, -0.5, 3.0]);
        assert_eq!(
            layer.weight().tensor().gradient().unwrap().as_slice(),
            &[0.5, -2.0, -2.0, 3.5, 6.0, 1.0]
        );
        assert_eq!(
            layer
                .bias()
                .unwrap()
                .tensor()
                .gradient()
                .unwrap()
                .as_slice(),
            &[1.5, 2.0, 0.0]
        );
    }

    #[test]
    fn vector_sequence_batch_and_empty_leading_axes_preserve_shape() {
        let layer = known_layer(true);
        for (shape, values, expected_shape, expected) in [
            (&[2][..], &[1.0, 2.0][..], &[3][..], &[5.5, 0.5, 2.0][..]),
            (
                &[2, 2],
                &[1.0, 2.0, -1.0, 3.0],
                &[2, 3],
                &[5.5, 0.5, 2.0, 5.5, 1.0, 5.0],
            ),
            (
                &[1, 2, 2],
                &[1.0, 2.0, -1.0, 3.0],
                &[1, 2, 3],
                &[5.5, 0.5, 2.0, 5.5, 1.0, 5.0],
            ),
        ] {
            let input = TensorValue::constant(tensor(shape, values)).unwrap();
            let output = layer.forward(&input).unwrap().value_snapshot();
            assert_eq!(output.shape(), expected_shape);
            assert_eq!(output.as_slice(), expected);
        }

        let empty = TensorValue::constant(tensor(&[0, 2], &[])).unwrap();
        let output = layer.forward(&empty).unwrap().value_snapshot();
        assert_eq!(output.shape(), &[0, 3]);
        assert!(output.is_empty());
    }

    #[test]
    fn rank_one_bias_free_backward_restores_the_vector_shape() {
        let layer = known_layer(false);
        let input = TensorValue::parameter(tensor(&[2], &[1.0, 2.0])).unwrap();
        let output = layer.forward(&input).unwrap();
        output
            .backward_with_seed(
                &tensor(&[3], &[1.0, 0.0, -1.0]).view(),
                GraphRetention::Retain,
            )
            .unwrap();

        assert_eq!(output.shape(), [3]);
        assert_eq!(input.gradient().unwrap().shape(), &[2]);
        assert_eq!(input.gradient().unwrap().as_slice(), &[2.0, 1.0]);
        assert_eq!(
