    #[test]
    fn optional_bias_changes_values_parameter_order_and_count_only_as_declared() {
        let affine = known_layer(true);
        let bias_free = known_layer(false);
        let input = TensorValue::constant(tensor(&[1, 2, 2], &[1.0, 2.0, -1.0, 3.0])).unwrap();
