    #[test]
    fn epsilon_dominates_tiny_values_and_stabilizes_zero() {
        let layer = RmsNorm::from_gain(gain(&[1.0, 1.0]), EPSILON).unwrap();
        let tiny = layer
            .forward(&TensorValue::constant(tensor(&[2], &[3e-4, 4e-4])).unwrap())
