        assert_eq!(mean_features.shape(), [2]);
        assert_eq!(mean_features.as_slice(), [2.0, 5.0]);
        assert_eq!(mean_features_kept.shape(), [2, 1]);
        assert_eq!(mean_features_kept.as_slice(), [2.0, 5.0]);
