    #[test]
    fn scalar_reduction_checks_axis_before_empty_rules() {
        let scalar = Tensor::from_vec(vec![], vec![7.0]).unwrap();
        assert_eq!(
            sum_axis(&scalar.view(), 0, false),
            Err(TensorOpError::ReductionAxisOutOfBounds { axis: 0, rank: 0 })
        );
    }

    #[test]
    fn maximum_propagates_first_nan_and_retains_earlier_equal_bits() {
        let first_nan_bits = 0x7ff8_0000_0000_0042;
        let second_nan_bits = 0x7ff8_0000_0000_0099;
        let values = Tensor::from_vec(
            vec![2, 3],
            vec![
                1.0,
                f64::from_bits(first_nan_bits),
                f64::from_bits(second_nan_bits),
                -0.0,
                0.0,
                -1.0,
            ],
        )
        .unwrap();
        let maximum = max_axis(&values.view(), 1, false).unwrap();

        assert_eq!(maximum.as_slice()[0].to_bits(), first_nan_bits);
        assert_eq!(maximum.as_slice()[1].to_bits(), (-0.0_f64).to_bits());

        let reversed_zero = Tensor::from_vec(vec![2], vec![0.0, -0.0]).unwrap();
        assert_eq!(
            max_axis(&reversed_zero.view(), 0, false)
                .unwrap()
                .as_slice()[0]
                .to_bits(),
            0.0_f64.to_bits()
        );
    }

    #[test]
    fn error_messages_and_sources_preserve_rejected_invariants() {
        let broadcast = TensorOpError::IncompatibleBroadcast {
            axis: 1,
            left_dimension: 3,
            right_dimension: 2,
        };
        assert_eq!(
            broadcast.to_string(),
            "cannot broadcast output axis 1: left size 3, right size 2"
        );
        assert_eq!(
            TensorOpError::ReductionAxisOutOfBounds { axis: 0, rank: 0 }.to_string(),
            "reduction axis 0 is out of bounds for rank 0"
        );
        assert_eq!(
            TensorOpError::EmptyMeanAxis { axis: 1 }.to_string(),
            "cannot compute mean over empty axis 1"
        );
        assert_eq!(
            TensorOpError::EmptyMaxAxis { axis: 1 }.to_string(),
            "cannot compute max over empty axis 1"
        );
        assert_eq!(
            TensorOpError::OutputAllocationFailed { elements: 6 }.to_string(),
            "cannot allocate output buffer for 6 f64 values"
        );
        assert!(broadcast.source().is_none());
        assert!(
            TensorOpError::Tensor(TensorError::ShapeOverflow)
                .source()
                .is_some()
        );
    }
}

//! Contiguous row-major tensor storage and checked coordinate lookup.

use std::error::Error;
use std::fmt;

/// A tensor whose logical dimensions map onto one contiguous value buffer.
#[derive(Clone, Debug, PartialEq)]
pub struct Tensor {
    data: Vec<f64>,
    shape: Vec<usize>,
    strides: Vec<usize>,
}

/// A rejected tensor layout, buffer, or coordinate.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum TensorError {
    /// A suffix product needed by the row-major layout exceeds `usize`.
    ShapeOverflow,
    /// The flat buffer length differs from the shape's element count.
    DataLengthMismatch { expected: usize, actual: usize },
    /// A coordinate supplies a different number of axes from the tensor.
    RankMismatch { expected: usize, actual: usize },
    /// One coordinate index lies outside its axis.
    IndexOutOfBounds {
        axis: usize,
        index: usize,
        dimension: usize,
    },
}

impl fmt::Display for TensorError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::ShapeOverflow => {
                formatter.write_str("shape does not fit a row-major usize layout")
            }
            Self::DataLengthMismatch { expected, actual } => write!(
                formatter,
                "shape needs {expected} values, but data has {actual}"
            ),
            Self::RankMismatch { expected, actual } => write!(
                formatter,
                "coordinate rank {actual} does not match tensor rank {expected}"
            ),
            Self::IndexOutOfBounds {
                axis,
                index,
                dimension,
            } => write!(
                formatter,
                "index {index} is out of bounds for axis {axis} with size {dimension}"
            ),
        }
    }
}

impl Error for TensorError {}

// region:tensor-storage-invariants
pub(crate) fn checked_row_major_layout(
    shape: &[usize],
) -> Result<(Vec<usize>, usize), TensorError> {
    if shape.is_empty() {
        return Ok((Vec::new(), 1));
    }

    let mut strides = vec![1; shape.len()];
    for axis in (0..shape.len() - 1).rev() {
        strides[axis] = shape[axis + 1]
            .checked_mul(strides[axis + 1])
            .ok_or(TensorError::ShapeOverflow)?;
    }

    let element_count = shape[0]
        .checked_mul(strides[0])
        .ok_or(TensorError::ShapeOverflow)?;
    Ok((strides, element_count))
}

pub(crate) fn checked_offset(
    shape: &[usize],
    strides: &[usize],
    base_offset: usize,
    coordinate: &[usize],
) -> Result<usize, TensorError> {
    debug_assert_eq!(shape.len(), strides.len());

    if coordinate.len() != shape.len() {
        return Err(TensorError::RankMismatch {
            expected: shape.len(),
            actual: coordinate.len(),
        });
    }

    let mut offset = base_offset;
    for (axis, ((&index, &dimension), &stride)) in
        coordinate.iter().zip(shape).zip(strides).enumerate()
    {
        if index >= dimension {
            return Err(TensorError::IndexOutOfBounds {
                axis,
                index,
                dimension,
            });
        }
        let contribution = index
            .checked_mul(stride)
            .ok_or(TensorError::ShapeOverflow)?;
        offset = offset
            .checked_add(contribution)
            .ok_or(TensorError::ShapeOverflow)?;
    }
    Ok(offset)
}

impl Tensor {
    /// Builds a tensor after checking its row-major layout and buffer length.
    pub fn from_vec(shape: Vec<usize>, data: Vec<f64>) -> Result<Self, TensorError> {
        let (strides, expected) = checked_row_major_layout(&shape)?;
        let actual = data.len();
        if actual != expected {
            return Err(TensorError::DataLengthMismatch { expected, actual });
        }

        Ok(Self {
            data,
            shape,
            strides,
        })
    }

    /// Returns the number of logical axes.
    pub fn rank(&self) -> usize {
        self.shape.len()
    }

    /// Returns the extent of every axis.
    pub fn shape(&self) -> &[usize] {
        &self.shape
    }

    /// Returns the row-major suffix-product stride for every axis.
    pub fn strides(&self) -> &[usize] {
        &self.strides
    }

    /// Returns the number of stored values.
    pub fn len(&self) -> usize {
        self.data.len()
    }

    /// Reports whether the flat buffer stores no values.
    pub fn is_empty(&self) -> bool {
        self.data.is_empty()
    }

    /// Borrows the contiguous value buffer.
    pub fn as_slice(&self) -> &[f64] {
        &self.data
    }

    /// Mutably borrows the contiguous value buffer without changing its length.
    pub fn as_mut_slice(&mut self) -> &mut [f64] {
        &mut self.data
    }

    /// Consumes the tensor and returns its contiguous value buffer.
    pub fn into_vec(self) -> Vec<f64> {
        self.data
    }
    // endregion:tensor-storage-invariants

    // region:row-major-indexing
    /// Maps one in-bounds coordinate to its row-major flat-buffer offset.
    pub fn offset(&self, coordinate: &[usize]) -> Result<usize, TensorError> {
        checked_offset(&self.shape, &self.strides, 0, coordinate)
    }

    /// Borrows the value at one checked coordinate.
    pub fn get(&self, coordinate: &[usize]) -> Result<&f64, TensorError> {
        let offset = self.offset(coordinate)?;
        Ok(&self.data[offset])
    }

    /// Mutably borrows the value at one checked coordinate.
    pub fn get_mut(&mut self, coordinate: &[usize]) -> Result<&mut f64, TensorError> {
        let offset = self.offset(coordinate)?;
        Ok(&mut self.data[offset])
    }
    // endregion:row-major-indexing
}

#[cfg(test)]
mod tests {
    use super::*;

    fn tiny_tensor() -> Tensor {
        Tensor::from_vec(
            vec![2, 2, 3],
            vec![
                10.0, 11.0, 12.0, 20.0, 21.0, 22.0, 30.0, 31.0, 32.0, 40.0, 41.0, 42.0,
            ],
        )
        .unwrap()
    }

    #[test]
    fn from_vec_freezes_contiguous_row_major_metadata() {
        let tensor = tiny_tensor();

        assert_eq!(tensor.rank(), 3);
        assert_eq!(tensor.shape(), [2, 2, 3]);
        assert_eq!(tensor.strides(), [6, 3, 1]);
        assert_eq!(tensor.len(), 12);
        assert!(!tensor.is_empty());
        assert_eq!(tensor.as_slice().first(), Some(&10.0));
        assert_eq!(tensor.as_slice().last(), Some(&42.0));
    }

    #[test]
    fn row_major_offsets_cover_every_value_once() {
        let tensor = tiny_tensor();
        let mut offsets = Vec::new();

        for axis0 in 0..2 {
            for axis1 in 0..2 {
                for axis2 in 0..3 {
                    let coordinate = [axis0, axis1, axis2];
                    let offset = tensor.offset(&coordinate).unwrap();
                    offsets.push(offset);
                    assert_eq!(tensor.get(&coordinate), Ok(&tensor.as_slice()[offset]));
                }
            }
        }

        assert_eq!(offsets, (0..12).collect::<Vec<_>>());
        assert_eq!(tensor.offset(&[1, 0, 2]), Ok(8));
        assert_eq!(tensor.get(&[1, 0, 2]), Ok(&32.0));
    }

    #[test]
    fn mutable_access_cannot_change_layout_invariants() {
        let mut tensor = tiny_tensor();

        *tensor.get_mut(&[0, 1, 1]).unwrap() = 99.0;
        tensor.as_mut_slice()[0] = -10.0;

        assert_eq!(tensor.get(&[0, 1, 1]), Ok(&99.0));
        assert_eq!(tensor.get(&[0, 0, 0]), Ok(&-10.0));
        assert_eq!(tensor.shape(), [2, 2, 3]);
        assert_eq!(tensor.strides(), [6, 3, 1]);
        assert_eq!(tensor.len(), 12);
    }

    #[test]
    fn into_vec_returns_values_in_flat_order() {
        let values = tiny_tensor().into_vec();

        assert_eq!(
            values,
            [
                10.0, 11.0, 12.0, 20.0, 21.0, 22.0, 30.0, 31.0, 32.0, 40.0, 41.0, 42.0,
            ]
        );
    }

    #[test]
    fn storage_preserves_arbitrary_f64_bit_patterns() {
        let values = vec![
            1.5,
            f64::INFINITY,
            -0.0,
            f64::from_bits(0x7ff8_0000_0000_0042),
        ];
        let expected_bits = values
            .iter()
            .map(|value| value.to_bits())
            .collect::<Vec<_>>();

        let actual_bits = Tensor::from_vec(vec![2, 2], values)
            .unwrap()
            .into_vec()
            .into_iter()
            .map(f64::to_bits)
            .collect::<Vec<_>>();

        assert_eq!(actual_bits, expected_bits);
    }

    #[test]
    fn rank_zero_is_one_scalar_value() {
        let tensor = Tensor::from_vec(vec![], vec![7.0]).unwrap();

        assert_eq!(tensor.rank(), 0);
        assert_eq!(tensor.shape(), &[] as &[usize]);
        assert_eq!(tensor.strides(), &[] as &[usize]);
        assert_eq!(tensor.len(), 1);
        assert_eq!(tensor.offset(&[]), Ok(0));
        assert_eq!(tensor.get(&[]), Ok(&7.0));
    }

    #[test]
    fn rank_n_has_no_hard_coded_axis_limit() {
        let shape = vec![1; 64];
        let coordinate = vec![0; 64];
        let tensor = Tensor::from_vec(shape.clone(), vec![5.0]).unwrap();

        assert_eq!(tensor.rank(), 64);
        assert_eq!(tensor.shape(), shape.as_slice());
        assert_eq!(tensor.strides(), &[1; 64]);
        assert_eq!(tensor.offset(&coordinate), Ok(0));
        assert_eq!(tensor.get(&coordinate), Ok(&5.0));
    }

    #[test]
    fn zero_extent_layout_is_valid_and_empty() {
        let tensor = Tensor::from_vec(vec![2, 0, 3], vec![]).unwrap();

        assert_eq!(tensor.strides(), [0, 3, 1]);
        assert_eq!(tensor.len(), 0);
        assert!(tensor.is_empty());
        assert_eq!(
            tensor.offset(&[0, 0, 0]),
            Err(TensorError::IndexOutOfBounds {
                axis: 1,
                index: 0,
                dimension: 0,
            })
        );
    }

    #[test]
    fn data_length_must_equal_shape_product() {
        assert_eq!(
            Tensor::from_vec(vec![2, 3], vec![0.0; 5]),
            Err(TensorError::DataLengthMismatch {
                expected: 6,
                actual: 5,
            })
        );
        assert_eq!(
            Tensor::from_vec(vec![2, 3], vec![0.0; 7]),
            Err(TensorError::DataLengthMismatch {
                expected: 6,
                actual: 7,
            })
        );
        assert_eq!(
            Tensor::from_vec(vec![], vec![]),
            Err(TensorError::DataLengthMismatch {
                expected: 1,
                actual: 0,
            })
        );
        assert_eq!(
            Tensor::from_vec(vec![0], vec![1.0]),
            Err(TensorError::DataLengthMismatch {
                expected: 0,
                actual: 1,
            })
        );
    }

    #[test]
    fn overflowing_shape_and_suffix_are_rejected_before_length() {
        assert_eq!(
            Tensor::from_vec(vec![usize::MAX, 2], vec![]),
            Err(TensorError::ShapeOverflow)
        );
        assert_eq!(
            Tensor::from_vec(vec![0, usize::MAX, 2], vec![]),
            Err(TensorError::ShapeOverflow)
        );
    }

    #[test]
    fn rank_is_validated_before_any_axis() {
        let tensor = tiny_tensor();

        assert_eq!(
            tensor.offset(&[usize::MAX]),
            Err(TensorError::RankMismatch {
                expected: 3,
                actual: 1,
            })
        );
        assert_eq!(
            tensor.offset(&[0, 0, 0, 0]),
            Err(TensorError::RankMismatch {
                expected: 3,
                actual: 4,
            })
        );
    }

    #[test]
    fn bounds_are_validated_in_axis_order() {
        let tensor = tiny_tensor();

        assert_eq!(
            tensor.offset(&[2, 2, 3]),
            Err(TensorError::IndexOutOfBounds {
                axis: 0,
                index: 2,
                dimension: 2,
            })
        );
        assert_eq!(
            tensor.offset(&[1, 2, 0]),
            Err(TensorError::IndexOutOfBounds {
                axis: 1,
                index: 2,
                dimension: 2,
            })
        );
        assert_eq!(
            tensor.offset(&[1, 1, 3]),
            Err(TensorError::IndexOutOfBounds {
                axis: 2,
                index: 3,
                dimension: 3,
            })
        );
    }

    #[test]
    fn error_messages_explain_the_rejected_invariant() {
        assert_eq!(
            TensorError::ShapeOverflow.to_string(),
            "shape does not fit a row-major usize layout"
        );
        assert_eq!(
            TensorError::DataLengthMismatch {
                expected: 6,
                actual: 5,
            }
            .to_string(),
            "shape needs 6 values, but data has 5"
        );
        assert_eq!(
            TensorError::RankMismatch {
                expected: 3,
                actual: 2,
            }
            .to_string(),
            "coordinate rank 2 does not match tensor rank 3"
        );
        assert_eq!(
            TensorError::IndexOutOfBounds {
                axis: 1,
                index: 2,
                dimension: 2,
            }
            .to_string(),
            "index 2 is out of bounds for axis 1 with size 2"
        );
    }
}

//! Borrowed tensor views with checked axis transforms and explicit materialization.

use std::error::Error;
use std::fmt;
use std::iter::FusedIterator;
use std::ops::Range;

use super::storage::{Tensor, TensorError, checked_offset, checked_row_major_layout};

/// A rejected tensor-view transform, slice, or coordinate.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum TensorViewError {
    /// The shared tensor layout or coordinate rules rejected an operation.
    Tensor(TensorError),
    /// An operation names an axis that the view does not have.
    AxisOutOfBounds { axis: usize, rank: usize },
    /// A permutation must name exactly one source axis per output axis.
    PermutationLengthMismatch { expected: usize, actual: usize },
    /// A permutation names one source axis more than once.
    DuplicateAxis { axis: usize },
    /// A half-open slice has its start after its end.
    SliceStartAfterEnd {
        axis: usize,
        start: usize,
        end: usize,
    },
    /// A half-open slice ends beyond its source-axis extent.
    SliceEndOutOfBounds {
        axis: usize,
        end: usize,
        dimension: usize,
    },
    /// A reshape requests a different number of logical elements.
    ReshapeElementCountMismatch { current: usize, requested: usize },
    /// This chapter only reshapes views whose logical order is row-major contiguous.
    NonContiguousReshape,
}

impl fmt::Display for TensorViewError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Tensor(error) => error.fmt(formatter),
            Self::AxisOutOfBounds { axis, rank } => {
                write!(formatter, "axis {axis} is out of bounds for rank {rank}")
            }
            Self::PermutationLengthMismatch { expected, actual } => write!(
                formatter,
                "permutation length {actual} does not match tensor rank {expected}"
            ),
            Self::DuplicateAxis { axis } => {
                write!(formatter, "permutation axis {axis} appears more than once")
            }
            Self::SliceStartAfterEnd { axis, start, end } => write!(
                formatter,
                "slice start {start} is after end {end} on axis {axis}"
            ),
            Self::SliceEndOutOfBounds {
                axis,
                end,
                dimension,
            } => write!(
                formatter,
                "slice end {end} is out of bounds for axis {axis} with size {dimension}"
            ),
            Self::ReshapeElementCountMismatch { current, requested } => write!(
                formatter,
                "cannot reshape {current} elements into {requested} elements"
            ),
            Self::NonContiguousReshape => formatter.write_str(
                "cannot reshape a non-row-major-contiguous view without materializing it",
            ),
        }
    }
}

impl Error for TensorViewError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            Self::Tensor(error) => Some(error),
            _ => None,
        }
    }
}

impl From<TensorError> for TensorViewError {
    fn from(error: TensorError) -> Self {
        Self::Tensor(error)
    }
}

// region:borrowed-tensor-view
/// An immutable n-dimensional interpretation of storage owned by a [`Tensor`].
///
/// The view copies only shape and stride metadata. Rust keeps the source tensor
/// borrowed for the view's lifetime, so safe code cannot mutate the owner while
/// a subsequently used view still exists:
///
/// ```compile_fail
/// use llm_from_scratch::tensor::storage::Tensor;
///
/// let mut tensor = Tensor::from_vec(vec![2], vec![10.0, 20.0]).unwrap();
/// let view = tensor.view();
/// tensor.as_mut_slice()[0] = 99.0;
/// assert_eq!(*view.get(&[0]).unwrap(), 10.0);
/// ```
#[derive(Clone, Debug, PartialEq)]
pub struct TensorView<'a> {
    source: &'a Tensor,
    shape: Vec<usize>,
    strides: Vec<usize>,
    base_offset: usize,
    len: usize,
}

impl Tensor {
    /// Borrows this tensor as a row-major-contiguous view without copying values.
    pub fn view(&self) -> TensorView<'_> {
        TensorView {
            source: self,
            shape: self.shape().to_vec(),
            strides: self.strides().to_vec(),
            base_offset: 0,
            len: self.len(),
        }
    }
}

impl<'a> TensorView<'a> {
    /// Returns the number of logical axes.
    pub fn rank(&self) -> usize {
        self.shape.len()
    }

    /// Returns the extent of every logical axis.
    pub fn shape(&self) -> &[usize] {
        &self.shape
    }

    /// Returns the source-storage movement for each logical axis.
    pub fn strides(&self) -> &[usize] {
        &self.strides
    }

    /// Returns the source-storage offset of the view's logical origin.
    pub fn base_offset(&self) -> usize {
        self.base_offset
    }

    /// Returns the number of logical values in the view.
    pub fn len(&self) -> usize {
        self.len
    }

    /// Reports whether the view has no logical values.
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    /// Reports whether logical row-major iteration visits one dense storage span.
    ///
    /// Singleton axes may carry any stride because they never advance. Scalars
    /// and empty views are contiguous by this chapter's explicit convention.
    pub fn is_contiguous(&self) -> bool {
        if self.is_empty() {
            return true;
        }

        let mut expected_stride = 1_usize;
        for (&dimension, &stride) in self.shape.iter().zip(&self.strides).rev() {
            if dimension > 1 && stride != expected_stride {
                return false;
            }
            expected_stride = expected_stride
                .checked_mul(dimension)
                .expect("a valid tensor view retains a checked shape");
        }
        true
    }

    /// Maps one checked logical coordinate to the owner's flat storage offset.
    pub fn storage_offset(&self, coordinate: &[usize]) -> Result<usize, TensorViewError> {
        checked_offset(&self.shape, &self.strides, self.base_offset, coordinate).map_err(Into::into)
    }

    /// Borrows the source value selected by one checked logical coordinate.
    pub fn get(&self, coordinate: &[usize]) -> Result<&'a f64, TensorViewError> {
        let offset = self.storage_offset(coordinate)?;
        let source: &'a [f64] = self.source.as_slice();
        Ok(&source[offset])
    }
}
// endregion:borrowed-tensor-view

// region:validated-strided-offset-iteration
/// Logical row-major traversal over a layout whose metadata was already checked.
///
/// The cursor owns one `O(rank)` axis-state vector and updates it in place. It
/// keeps no tensor borrow, so later kernels can use the same plumbing for source
/// reads or destination writes. It remains crate-private so arbitrary external
/// coordinates still enter through [`TensorView::storage_offset`] or
/// [`TensorView::get`].
#[derive(Clone, Copy, Debug)]
struct OffsetAxis {
    extent: usize,
    stride: usize,
    position: usize,
    rewind: usize,
}

#[derive(Debug)]
pub(crate) struct StridedOffsets {
    axes: Vec<OffsetAxis>,
    next_offset: usize,
    remaining: usize,
}

impl StridedOffsets {
    /// Checks one internal traversal plan and then owns its reusable axis state.
    pub(crate) fn checked(
        shape: &[usize],
        strides: &[usize],
        base_offset: usize,
        logical_len: usize,
        backing_len: usize,
    ) -> Option<Self> {
        if shape.len() != strides.len() {
            return None;
        }

        let expected_len = if shape.contains(&0) {
            0
        } else {
            shape
                .iter()
                .try_fold(1_usize, |count, &extent| count.checked_mul(extent))?
        };
        if logical_len != expected_len {
            return None;
        }

        if logical_len == 0 {
            return Some(Self {
                axes: shape
                    .iter()
                    .zip(strides)
                    .map(|(&extent, &stride)| OffsetAxis {
                        extent,
                        stride,
                        position: 0,
                        rewind: 0,
                    })
                    .collect(),
                next_offset: base_offset,
                remaining: 0,
            });
        }

        let mut maximum_offset = base_offset;
        let mut axes = Vec::with_capacity(shape.len());
        for (&extent, &stride) in shape.iter().zip(strides) {
            let rewind = (extent - 1).checked_mul(stride)?;
            maximum_offset = maximum_offset.checked_add(rewind)?;
            axes.push(OffsetAxis {
                extent,
                stride,
                position: 0,
                rewind,
            });
        }
        if maximum_offset >= backing_len {
            return None;
        }

        Some(Self {
            axes,
            next_offset: base_offset,
            remaining: logical_len,
        })
    }

    fn advance(&mut self) {
        for axis in self.axes.iter_mut().rev() {
            let next_position = axis.position + 1;
            if next_position < axis.extent {
                axis.position = next_position;
                self.next_offset = self
                    .next_offset
                    .checked_add(axis.stride)
                    .expect("a checked traversal cannot overflow while advancing");
                return;
            }

            axis.position = 0;
            self.next_offset = self
                .next_offset
                .checked_sub(axis.rewind)
                .expect("a checked traversal cannot underflow while carrying");
        }

        unreachable!("a checked nonempty traversal advances within its logical shape");
    }
}

impl Iterator for StridedOffsets {
    type Item = usize;

    fn next(&mut self) -> Option<Self::Item> {
        if self.remaining == 0 {
            return None;
        }

        let offset = self.next_offset;
        self.remaining -= 1;
        if self.remaining != 0 {
            self.advance();
        }
        Some(offset)
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        (self.remaining, Some(self.remaining))
    }
}

impl ExactSizeIterator for StridedOffsets {}
impl FusedIterator for StridedOffsets {}

impl<'a> TensorView<'a> {
    /// Traverses this already validated view in logical row-major order.
    pub(crate) fn logical_offsets(&self) -> StridedOffsets {
        self.projected_offsets(&self.shape, &self.strides, self.len)
            .expect("a TensorView retains checked traversal metadata")
    }

    /// Checks effective strides for another logical traversal of this source.
    pub(crate) fn projected_offsets(
        &self,
        iteration_shape: &[usize],
        effective_strides: &[usize],
        logical_len: usize,
    ) -> Option<StridedOffsets> {
        StridedOffsets::checked(
            iteration_shape,
            effective_strides,
            self.base_offset,
            logical_len,
            self.source.len(),
        )
    }

    /// Copies one source scalar selected by an offset from a checked plan.
    pub(crate) fn value_at_storage_offset(&self, offset: usize) -> f64 {
        self.source.as_slice()[offset]
    }
}
// endregion:validated-strided-offset-iteration

impl<'a> TensorView<'a> {
    // region:view-axis-transforms
    /// Reinterprets a row-major-contiguous view with a compatible shape.
    pub fn reshape(&self, shape: &[usize]) -> Result<Self, TensorViewError> {
        let (strides, requested) = checked_row_major_layout(shape)?;
        if requested != self.len {
            return Err(TensorViewError::ReshapeElementCountMismatch {
                current: self.len,
                requested,
            });
        }
        if !self.is_contiguous() {
            return Err(TensorViewError::NonContiguousReshape);
        }

        Ok(Self {
            source: self.source,
            shape: shape.to_vec(),
            strides,
            base_offset: self.base_offset,
            len: self.len,
        })
    }

    /// Swaps two logical axes without moving source values.
    pub fn transpose(&self, first: usize, second: usize) -> Result<Self, TensorViewError> {
        self.check_axis(first)?;
        self.check_axis(second)?;

        let mut axes = (0..self.rank()).collect::<Vec<_>>();
        axes.swap(first, second);
        self.permute(&axes)
    }

    /// Reorders axes so output axis `k` uses source axis `axes[k]`.
    pub fn permute(&self, axes: &[usize]) -> Result<Self, TensorViewError> {
        if axes.len() != self.rank() {
            return Err(TensorViewError::PermutationLengthMismatch {
                expected: self.rank(),
                actual: axes.len(),
            });
        }

        let mut seen = vec![false; self.rank()];
        for &axis in axes {
            self.check_axis(axis)?;
            if seen[axis] {
                return Err(TensorViewError::DuplicateAxis { axis });
            }
            seen[axis] = true;
        }

        Ok(Self {
            source: self.source,
            shape: axes.iter().map(|&axis| self.shape[axis]).collect(),
            strides: axes.iter().map(|&axis| self.strides[axis]).collect(),
            base_offset: self.base_offset,
            len: self.len,
        })
    }
    // endregion:view-axis-transforms

    // region:view-slice-materialize
    /// Selects a half-open, unit-step range on one axis without copying values.
    pub fn slice(&self, axis: usize, range: Range<usize>) -> Result<Self, TensorViewError> {
        self.check_axis(axis)?;
        if range.start > range.end {
            return Err(TensorViewError::SliceStartAfterEnd {
                axis,
                start: range.start,
                end: range.end,
            });
        }

        let dimension = self.shape[axis];
        if range.end > dimension {
            return Err(TensorViewError::SliceEndOutOfBounds {
                axis,
                end: range.end,
                dimension,
            });
        }

        let start_offset = range
            .start
            .checked_mul(self.strides[axis])
            .ok_or(TensorViewError::Tensor(TensorError::ShapeOverflow))?;
        let base_offset = self
            .base_offset
            .checked_add(start_offset)
            .ok_or(TensorViewError::Tensor(TensorError::ShapeOverflow))?;
        let mut shape = self.shape.clone();
        shape[axis] = range.end - range.start;
        let (_, len) = checked_row_major_layout(&shape)?;

        Ok(Self {
            source: self.source,
            shape,
            strides: self.strides.clone(),
            base_offset,
            len,
        })
    }

    /// Copies logical row-major values into a new owned, contiguous tensor.
    pub fn materialize(&self) -> Result<Tensor, TensorViewError> {
        let mut values = Vec::with_capacity(self.len);
        for storage_offset in self.logical_offsets() {
            values.push(self.value_at_storage_offset(storage_offset));
        }
        Tensor::from_vec(self.shape.clone(), values).map_err(Into::into)
    }
    // endregion:view-slice-materialize

    fn check_axis(&self, axis: usize) -> Result<(), TensorViewError> {
        if axis >= self.rank() {
            return Err(TensorViewError::AxisOutOfBounds {
                axis,
                rank: self.rank(),
            });
        }
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn matrix() -> Tensor {
        Tensor::from_vec(vec![2, 3], vec![10.0, 11.0, 12.0, 20.0, 21.0, 22.0]).unwrap()
    }

    fn checked_logical_offsets(view: &TensorView<'_>) -> Vec<usize> {
        (0..view.len())
            .map(|mut logical_offset| {
                let mut coordinate = vec![0; view.rank()];
                for axis in (0..view.rank()).rev() {
                    coordinate[axis] = logical_offset % view.shape()[axis];
                    logical_offset /= view.shape()[axis];
                }
                view.storage_offset(&coordinate).unwrap()
            })
            .collect()
    }

    fn assert_validated_offsets_match_checked(view: &TensorView<'_>) {
        assert_eq!(
            view.logical_offsets().collect::<Vec<_>>(),
            checked_logical_offsets(view)
        );
    }

    #[test]
    fn identity_view_borrows_owned_storage() {
        let tensor = matrix();
        let view = tensor.view();

        assert_eq!(view.rank(), 2);
        assert_eq!(view.shape(), [2, 3]);
        assert_eq!(view.strides(), [3, 1]);
        assert_eq!(view.base_offset(), 0);
        assert_eq!(view.len(), 6);
        assert!(!view.is_empty());
        assert!(view.is_contiguous());
        assert_eq!(view.storage_offset(&[1, 2]), Ok(5));
        assert_eq!(view.get(&[1, 2]), Ok(&22.0));
        assert!(std::ptr::eq(
            tensor.get(&[1, 2]).unwrap(),
            view.get(&[1, 2]).unwrap()
        ));
    }

    #[test]
    fn compatible_reshape_preserves_linear_order_and_storage() {
        let tensor = matrix();
        let reshaped = tensor.view().reshape(&[3, 2]).unwrap();

        assert_eq!(reshaped.shape(), [3, 2]);
        assert_eq!(reshaped.strides(), [2, 1]);
        assert_eq!(reshaped.base_offset(), 0);
        assert!(reshaped.is_contiguous());
        assert_eq!(reshaped.get(&[2, 1]), Ok(&22.0));
        assert!(std::ptr::eq(
            tensor.get(&[1, 2]).unwrap(),
            reshaped.get(&[2, 1]).unwrap()
        ));
    }

    #[test]
    fn reshape_checks_layout_then_count_then_contiguity() {
        let tensor = matrix();
        let transposed = tensor.view().transpose(0, 1).unwrap();

        assert_eq!(
            transposed.reshape(&[0, usize::MAX, 2]),
            Err(TensorViewError::Tensor(TensorError::ShapeOverflow))
        );
        assert_eq!(
            transposed.reshape(&[4, 2]),
            Err(TensorViewError::ReshapeElementCountMismatch {
                current: 6,
                requested: 8,
            })
        );
        assert_eq!(
            transposed.reshape(&[2, 3]),
            Err(TensorViewError::NonContiguousReshape)
        );
    }

    #[test]
    fn transpose_and_permutation_change_axes_not_values() {
        let tensor = matrix();
        let transposed = tensor.view().transpose(0, 1).unwrap();
        let permuted = tensor.view().permute(&[1, 0]).unwrap();

        assert_eq!(transposed.shape(), [3, 2]);
        assert_eq!(transposed.strides(), [1, 3]);
        assert!(!transposed.is_contiguous());
        assert_eq!(transposed.get(&[2, 1]), Ok(&22.0));
        assert_eq!(permuted.shape(), transposed.shape());
        assert_eq!(permuted.strides(), transposed.strides());
        assert_eq!(permuted.storage_offset(&[2, 1]), Ok(5));
        assert!(std::ptr::eq(
            tensor.get(&[1, 2]).unwrap(),
            transposed.get(&[2, 1]).unwrap()
        ));
        assert_eq!(tensor.as_slice(), [10.0, 11.0, 12.0, 20.0, 21.0, 22.0]);
    }

    #[test]
    fn rank_three_permutation_moves_matching_extents_and_strides() {
        let tensor = Tensor::from_vec(vec![2, 3, 4], (0..24).map(f64::from).collect()).unwrap();
        let permuted = tensor.view().permute(&[2, 0, 1]).unwrap();

        assert_eq!(permuted.shape(), [4, 2, 3]);
        assert_eq!(permuted.strides(), [1, 12, 4]);
        assert_eq!(permuted.storage_offset(&[3, 1, 2]), Ok(23));
