impl AdamWConfig {
    /// Revalidates only the scheduled learning rate while preserving AdamW's
    /// moment and decay controls.
    pub fn with_learning_rate(self, learning_rate: f64) -> Result<Self, AdamWError> {
        Self::new(
            learning_rate,
            self.beta1,
            self.beta2,
            self.epsilon,
