    #[test]
    fn final_batch_divides_loss_and_gradients_by_its_actual_token_count() {
        let epoch = MiniBatchEpoch::build(
            Partition::Train,
            &documents(),
            window_config(),
            config(3, BatchOrder::Sequential),
        )
        .unwrap();
        let final_batch = &epoch.batches()[1];
        let contributions = [
