            .unwrap();

        assert_eq!(final_batch.batch_width(), 2);
        assert_eq!(final_batch.token_count(), 4);
        assert_eq!(mean.token_count(), 4);
        assert_eq!(mean.mean_loss(), 0.625);
        assert_eq!(mean.mean_gradient(), [1.25, 1.375]);
        assert_eq!(
